insert into public.recipes (id, slug, name, description, difficulty, estimated_minutes, servings, required_tools, category, subcategory) values
('469708f2-a8d3-43d4-8f27-a02935822037', 'air-fryer-peanut-chicken-4519ed', 'Air Fryer Peanut Chicken', 'In this air fryer peanut chicken recipe, boneless, skinless chicken thighs are marinated in a spicy-sweet peanut marinade. Rice or noodles work with this dish, or cut it into bite-sized pieces and serve over a salad.', 4, 52, 2, ARRAY['에어프라이어', '냄비', '칼', '믹서']::text[], 'Air Fryer Recipes', 'Air Fryer Recipes'),
('94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 'loaded-cheeseburger-waffle-fry-bake-231610', 'Loaded Cheeseburger Waffle Fry Bake', 'Waffle fries, ground beef, bacon, cheese combine in this easy bake reminiscent of a Cheeseburger.', 3, 35, 2, ARRAY['에어프라이어', '오븐', '프라이팬', '칼']::text[], 'Beef Recipes', 'Beef Recipes'),
('95905e51-d14d-4651-893f-b8f09c0cb81f', 'lyonnaise-potatoes-b2f004', 'Lyonnaise Potatoes', 'These Lyonnaise potatoes are a classic dish made with sliced potatoes and onions.', 2, 22, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Healthy Recipes', 'Low-Sodium Recipes'),
('d24a9667-61c9-4802-8b8d-33c7b7a0fad7', 'maria-s-portuguese-bacalau-f078c0', 'Maria''s Portuguese Bacalau', 'This is a traditional Portuguese dish that brings back memories of mom. It is not only tasty but it is always a hit at parties. Plan ahead, because the salted cod (aka bacalhau or bacalao) needs to soak for 24 hours.', 3, 40, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Casseroles', 'Seafood Casserole'),
('cebef81f-9ad0-42ab-83de-3016327c779c', 'peppers-stuffed-with-grilled-chicken-and-rice-f4f778', 'Peppers Stuffed with Grilled Chicken and Rice', 'Randomly threw a few things together one night with some chicken and the stuffed bell peppers turned out to be one of my husband''s favorite meals! I''m quite proud of it!', 3, 93, 2, ARRAY['오븐', '냄비', '프라이팬', '그릴', '칼', '믹서']::text[], 'Main Dishes', 'Stuffed Bell Peppers'),
('e2d84739-a6ee-4f0d-89df-7b167628c620', 'scotch-eggs-5e3f66', 'Scotch Eggs', 'Scotch eggs are soft-boiled eggs wrapped in sausage and bread crumbs, deep-fried for a delicious savory treat. They''re a British pub favorite, perfect for family occasions or picnics. We like to make these on Christmas Eve served on a bed of lettuce with sliced tomatoes and mustard for garnish.', 2, 21, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Breakfast And Brunch', 'Breakfast And Brunch'),
('f04b1e52-24a8-4f5b-8aad-35b17acf824d', 'shepherd-s-pie-7e07c5', 'Shepherd''s Pie', 'Make this shepherd''s pie with ground beef or lamb, carrots, and onions in a rich gravy. Top with a layer of cheesy mashed potato to satisfy even the pickiest of eaters. It''s a great way to sneak some extra veggies into dinner!', 4, 56, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Beef Recipes', 'Beef Pie'),
('cd59422f-afa1-4644-8561-833a48b22296', 'shrimp-tostadas-628906', 'Shrimp Tostadas', 'Salad, side, main dish, and bread all in a little stack? Yes, please! Make that two! The slaw, refried black beans, and shrimp stack up on crispy tostada shells for a fun and tasty dinner. If your family likes milder heat, use only one chipotle pepper, and omit the cayenne.', 2, 6, 2, ARRAY['오븐', '냄비', '프라이팬', '칼', '믹서']::text[], 'Mexican', 'Authentic Mexican Recipes'),
('deec6010-176c-445a-88c8-9e523639499b', 'southeast-asian-style-chicken-rice-f94886', 'Southeast Asian Style Chicken Rice', 'I''ve mixed elements of Vietnamese, Thai, Indonesian and other Asian cuisines to make a delicious chicken and rice dish topped with a fresh herb salad.', 3, 62, 2, ARRAY['냄비', '프라이팬', '칼']::text[], 'Cooking For Two', 'Cooking For Two'),
('06689175-403c-4ac6-8f0a-f2ca327d5412', 'black-bean-lasagna-ii-09c8fe', 'Black Bean Lasagna II', 'Lasagna with a Southwest twist. This can be frozen unbaked and kept for up to a month. Simply thaw in refrigerator overnight and bake as directed. Tastes even better reheated the second day!', 4, 54, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Lasagna', 'Vegetarian Lasagna'),
('9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 'empanada-pie-a0d501', 'Empanada Pie', 'Serve this empanada pie with a salad, hard-boiled eggs, salsa or sour cream, and shredded Mexican cheese (optional).', 4, 99, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Empanadas', 'Empanadas'),
('fccaa0bb-7114-4d7e-877b-d0c691236135', 'air-fryer-french-fries-b4690e', 'Air Fryer French Fries', 'This air fryer French fries recipe includes a cold water-hot water soaking trick that produces super crispy French fries. Made with just four ingredients, these fries rival traditional fries but use a fraction of the oil. Serve with burgers, steak, or chicken with something to dip them in, like honey mustard, spicy ketchup, or garlic aioli.', 1, 50, 2, ARRAY['에어프라이어', '냄비', '칼']::text[], 'Air Fryer Recipes', 'Air Fryer Side Dish Recipes'),
('30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 'air-fryer-tostones-792e0d', 'Air Fryer Tostones', 'Tostones are made with green (unripe) plantains and are a very popular side dish in many Caribbean and South American countries. The traditional method is to twice-fry the plantains in oil, but this air-fried version of my Puerto Rican family''s recipe is much lighter as it uses olive oil spray instead of deep-frying.', 1, 15, 2, ARRAY['에어프라이어', '칼']::text[], 'Appetizers And Snacks', 'Fruit Appetizers'),
('6bc9bf6c-af62-4164-869b-9afd70a52ca9', 'authentic-tacos-al-pastor-d60d71', 'Authentic Tacos al Pastor', 'Tacos al pastor is a quintessential Mexican dish, with tender pork and pineapple marinated in a savory and aromatic chile sauce. Serve with warm corn tortillas, tomatillos salsa, and lemon or lime wedges.', 4, 20, 2, ARRAY['냄비', '그릴', '칼', '믹서']::text[], 'Cooking For A Crowd', 'Cooking For A Crowd Main Dishes'),
('87593681-0e4c-41e9-89d4-60038027a1b7', 'bacon-jalapen-o-popper-puffs-bcaf9d', 'Bacon Jalapeño Popper Puffs', 'If you enjoy the gut bombs that are classic, bacon-wrapped, jalapeño poppers, I think you''ll love this recipe for shockingly light puffs. All the same flavors are there, especially when served with the easy cream cheese dip, and the prep is much easier.', 1, 52, 2, ARRAY['프라이팬', '칼']::text[], 'July 4Th', '4Th Of July Appetizers'),
('b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 'baked-philly-cheesesteak-sliders-f2ae68', 'Baked Philly Cheesesteak Sliders', 'These baked cheesesteak sliders let you achieve something close to a proper Philly cheesesteak at home. Plus, the small rolls make me feel like a big man! Speaking of feeling like a giant, football season is upon us, and I can''t think of a better sandwich to make for your buddies coming over to watch the game.', 3, 30, 2, ARRAY['오븐', '프라이팬', '칼']::text[], 'Beef Recipes', 'Hamburgers'),
('c9c26bac-4f40-4181-8691-1414747c49dd', 'baked-pumpkin-polenta-26d609', 'Baked Pumpkin Polenta', 'Chef John''s baked pumpkin polenta gives a savory pumpkin twist to polenta prepared in an interesting, visually appealing, baked form. It is so soft and creamy inside a crust that holds its shape, subtly sweet and earthy.', 3, 55, 2, ARRAY['오븐', '냄비']::text[], 'Chef John', 'Chef John''S Side Dishes'),
('88e30023-5bb9-40cb-8124-d8e26dce3fc1', 'beef-bourguignon-i-03e627', 'Beef Bourguignon I', 'This rich beef bourguignon smells incredible as it cooks and brings my teenaged boys running! Serve this hearty yet fancy dish with potatoes, noodles, or rice.', 3, 21, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Beef Recipes', 'Beef Stew'),
('12b23cd5-03eb-452e-8c9c-8db9839f6d78', 'beef-pho-254254', 'Beef Pho', 'This beef pho features a comforting, richly-seasoned meat broth ladled over rice noodles and thinly sliced sirloin. Serve with hoisin, Sriracha, green onion, cilantro, bean sprouts, basil, and lime.', 4, 21, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Beef Recipes', 'Veal Recipes'),
('41518416-0bd8-465b-80a0-01f7cf6961dd', 'beef-tenderloin-with-roasted-shallots-bdc0d7', 'Beef Tenderloin With Roasted Shallots', 'The shallot sauce takes some time, but is well worth the trouble. This is definitely a company dish, and the recipe doubles well for a larger party. Serve with a green salad and roasted vegetables.', 3, 92, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Beef Recipes', 'Beef Short Loin'),
('8f14fb9c-6aef-4b36-8665-03c0792363f0', 'beet-orange-and-apple-salad-e27eb5', 'Beet, Orange, and Apple Salad', 'This beet and orange salad is a nice, colorful salad. Wedges of cooked beets, sliced apples, and orange sections are dressed with a delicious vinaigrette and spooned onto a bed of shredded beet greens.', 3, 20, 2, ARRAY['냄비', '칼']::text[], 'Easter', 'Easter Salads'),
('014759da-9af1-4725-8279-9d4d85540b04', 'brown-butter-carrot-sheet-cake-with-brown-butter-cream-cheese-frosting-d7b49b', 'Brown Butter Carrot Sheet Cake with Brown Butter-Cream Cheese Frosting', 'This carrot cake not only feeds a crowd, but it also gets an extra delicious flavor from the addition of brown butter to both the cake and the frosting. Top cake with candied carrot slices and toasted finely chopped walnuts, if desired.', 4, 95, 2, ARRAY['오븐', '냄비', '칼', '믹서']::text[], 'Cakes', 'Carrot Cake'),
('f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 'bruschetta-chicken-pasta-salad-e4e486', 'Bruschetta Chicken Pasta Salad', 'Summertime is the perfect time for all things pasta salad and grilling related. This bruschetta chicken pasta salad is bursting with flavor and topped with vibrant colorful tomatoes.', 3, 22, 2, ARRAY['냄비', '그릴', '칼']::text[], 'Pasta Salads', 'Pasta Salads'),
('fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 'buffalo-chicken-wings-in-a-jar-9842bd', 'Buffalo Chicken Wings in a Jar', 'This fun-sized take on the game day appetizer offers everything you love about Buffalo wings, minus the bones, messy frying, and any risk of your drunk friends dripping sauce all over the place. Instead of wings, we simply take chicken thighs, simmer them directly in butter ''n hot sauce, shred, and mix with celery. The blue cheese comes in the accompanying crostini: baguette slices toasted and spread with butter and blue cheese.', 2, 88, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Buffalo Chicken Wings', 'Buffalo Chicken Wings'),
('f26e0fdf-d47b-432e-8968-06e0f002aa31', 'chicageaux-spicy-smokehouse-tots-ca9d22', 'Chicageaux Spicy Smokehouse Tots', 'These tater tots are loaded with saucy, spicy chicken, cheese, and queso blanco. We kept it spicy for the great folks at Frank''s Red Hot.', 3, 31, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Casseroles', 'Chicken Casserole'),
('dff0c484-1553-4f0a-8803-68da4c42d4f7', 'chopped-liver-the-real-mccoy-f6536c', 'Chopped Liver the Real Mccoy', 'No recipe site is complete without a real recipe for real chopped liver. This makes for a great appetizer or spread for a pastrami and corned beef sandwich.', 3, 57, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Hanukkah', 'Hanukkah Appetizers'),
('982abbc8-08d6-4c65-8738-df00d4b9fc13', 'chorizo-queso-potato-bombs-d3502f', 'Chorizo Queso Potato Bombs', 'Try these chorizo queso potato bombs if you feel like trying out something new. The perfect appetizer, they are crunchy on the outside and rich and creamy on the inside.', 2, 23, 2, ARRAY['냄비', '칼']::text[], 'Appetizers And Snacks', 'Cheese Appetizers'),
('dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 'classic-beef-empanadas-b9b187', 'Classic Beef Empanadas', 'This authentic empanada recipe is for Argentinian beef empanadas filled with a savory and delicious mixture of ground beef, hard-cooked eggs, green olives, and potatoes. These classic empanadas are ubiquitous all over Argentina.', 4, 59, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Appetizers And Snacks', 'Pastry Appetizers'),
('c84f6946-ce78-4367-89c8-0abc7603546f', 'comforting-scalloped-potatoes-712882', 'Comforting Scalloped Potatoes', 'Spread warm wishes and full bellies with this delightful dish from Amber Wilson of For The Love Of The South', 2, 64, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Easter', 'Scalloped Potatoes'),
('e4c8851a-192a-40a8-800b-6a29cb1a36d4', 'copycat-chicken-fritta-d68edd', 'Copycat Chicken Fritta', 'This copycat chicken fritta features juicy fried chicken cutlets with a delicate, lightly crisp Asiago and breadcrumb crust, served over fettuccine in a luxurious, creamy Asiago cheese sauce. You''ll love this homemade version of the Olive Garden favorite.', 4, 19, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Italian', 'Italian'),
('eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 'crispy-turnip-fries-014ac3', 'Crispy Turnip "Fries"', 'Delicious crispy turnip "fries." My daughters and I are on a low-carb diet and were looking for something to curb our French fry cravings. I''ve heard that turnips can be made into some great fries. I experimented with it and came up with this. You can add whatever spices you''d like.', 2, 20, 2, ARRAY['오븐']::text[], 'Low Calorie', 'Low-Calorie Side Dishes'),
('8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 'decadent-cinnamon-roll-peach-cobbler-92395a', 'Decadent Cinnamon Roll Peach Cobbler', 'This peach cobbler is easy to make and very decadent. The use of store-bought cinnamon rolls makes it even faster to make. Serve with vanilla ice cream, if desired.', 2, 54, 2, ARRAY['오븐', '냄비']::text[], 'Cobblers', 'Peach Cobbler'),
('0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 'easy-baked-falafel-with-cucumber-yogurt-sauce-9ba7ac', 'Easy Baked Falafel with Cucumber-Yogurt Sauce', 'Try this Middle Eastern sandwich of chickpea and spice ''meatballs,'' which are actually falafel that are oven-fried to keep their calorie count down. Serve with grilled pita wedges or pita pockets, diced tomatoes, shredded lettuce, and cucumber slices.', 4, 36, 2, ARRAY['오븐', '그릴', '칼']::text[], 'Falafel', 'Falafel'),
('30437522-da47-49c9-8b17-065100b09ff8', 'eggplant-rollatini-70e054', 'Eggplant Rollatini', 'After having a delicious eggplant rollatini at an Italian restaurant, I decided I just had to learn how to make it! Hope you enjoy my recipe.', 3, 18, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Main Dishes', 'Fall Main Dishes'),
('3d5e8391-0b20-4f86-8de8-2f47b0f17658', 'homemade-gluten-free-gnocchi-04d794', 'Homemade Gluten-Free Gnocchi', 'This gluten-free gnocchi tastes like potatoes with a bouncy texture, even without gluten. This recipe uses a trick from the past when Italian cooks would toss potatoes into a fire or oven that was being cooled down so as not to waste the heat. Surplus baked potatoes became gnocchi because they have very little moisture (the secret to firm gnocchi) and they have a roasted potato flavor which is delicious!', 2, 67, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Dumplings', 'Dumplings'),
('00f3ed38-4474-4722-8d75-845db3662157', 'hot-bean-and-bacon-dip-with-air-fryer-tortilla-chips-1d110a', 'Hot Bean and Bacon Dip with Air Fryer Tortilla Chips', 'This is a great dip for game day, potlucks, or get-togethers. We serve it with air-fried tortilla chips. Leftovers are great (but you probably won''t have any) in a flour tortilla for a bean and cheese burrito, or roll it in a corn tortilla for a quick taco.', 4, 56, 2, ARRAY['에어프라이어', '오븐', '냄비', '프라이팬', '칼']::text[], 'Nachos', 'Nachos'),
('608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 'hychin-71b15d', 'Hychin', 'Hychin is a traditional dish of the Balkar people, from the Caucasus mountains in Russia (Elbrus region). These flatbreads with a cheese and potato filling are traditionally cooked in a cast-iron skillet and served with garlic and dill sauce on the side.', 2, 64, 2, ARRAY['냄비', '프라이팬', '칼']::text[], 'Breads', 'Flat Bread'),
('98da70d7-b8a7-42b5-88ab-c8c000c0796b', 'i-tried-giada-s-sheet-pan-lasagna-method-and-am-never-going-back-694dac', 'I Tried Giada''s Sheet Pan Lasagna Method and am Never Going Back', 'This spinach and artichoke sheet pan lasagna, inspired by Giada''s viral recipe, is loaded with sausage, spinach, and artichokes. It''s cheesy, golden, and bubbly, with all of the lasagna goodness you expect, but the assembly is much simpler.', 4, 39, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Dinner', 'Sheet Pan Dinners'),
('3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 'jalapen-o-bacon-cheddar-deviled-eggs-c8b451', 'Jalapeño Bacon Cheddar Deviled Eggs', 'This jalapeño bacon Cheddar deviled eggs recipe is a spin on an old classic — deviled eggs with the addition of savory bacon, delicious Cheddar, and spicy jalapeño.', 2, 25, 2, ARRAY['냄비', '프라이팬', '칼']::text[], 'Appetizers And Snacks', 'Deviled Eggs'),
('9ad6f83e-c441-4a91-84ce-3c3475373cf0', 'joy-s-green-banana-salad-bddff8', 'Joy''s Green Banana Salad', 'A recipe from my kitchen when I was in Puerto Rico made with green bananas, sweet onion and bacon in a vinegar dressing. I have served it to my North American friends and they love it as well. It is great to serve instead of the same ol'' potato salad. Dare to try something new?', 3, 5, 2, ARRAY['냄비', '프라이팬', '칼']::text[], 'Fruit Salads', 'Fruit Salads'),
('a7da003c-4ec6-433a-817a-2007ed13e26b', 'lemon-chicken-piccata-6203bc', 'Lemon Chicken Piccata', 'This delicious chicken piccata dish is exquisite and easy to prepare. The light and luscious lemon sauce really pops without being too acidic; it is simply divine. I love to serve this with herb-roasted potatoes or lemon-rice pilaf.', 3, 15, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Mother''S Day', 'Mother''S Day'),
('68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 'mashed-potato-au-gratin-8c3b34', 'Mashed Potato au Gratin', 'This spectacular mashed potato au gratin is my favorite potato side dish, mashed potatoes, topped with my other favorite potato side dish, potatoes au gratin. Beautiful, buttery mashed potatoes, with crusty, cheesy potatoes on top—it''s a whole new exciting way to eat potatoes.', 2, 18, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Chef John', 'Chef John''S Side Dishes'),
('ee4c8735-2376-41a2-816a-d0184aaf437d', 'mediterranean-casserole-7b4622', 'Mediterranean Casserole', 'Whether you''re on a diet or just like to eat Italian cooking with flavor, this is the perfect choice for you. In Italy it is usually served after an entree, but can also be eaten as a main dish with a tossed salad.', 2, 40, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Casseroles', 'Seafood Casserole'),
('80640f12-2148-4b50-8637-f83a257d54e5', 'melanzane-alla-parmigiana-eggplant-parmesan-89de5e', 'Melanzane alla Parmigiana (Eggplant Parmesan)', 'Melanzane alla parmigiana is a classic Italian dish from Sicily that''s often simply referred to as "parmigiana" by Sicilian locals. The richness and depth of flavor you get from this authentic version is well worth the extra effort. Serve eggplant Parmesan with nothing more than crusty bread and a green salad.', 3, 53, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Eggplant Parmesan', 'Eggplant Parmesan'),
('228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 'mini-philly-cheesesteaks-3d8d74', 'Mini Philly Cheesesteaks', 'Miniaturized sandwiches don''t usually float my boat, as they''re almost always not as good as the full-sized versions. But this mini Philly cheesesteak recipe captures everything I love about the classic.', 2, 31, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Appetizers And Snacks', 'Canapes And Crostini'),
('bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 'mom-s-pasta-al-forno-993226', 'Mom''s Pasta al Forno', 'Mom used to make this pasta al forno on special days, like on holidays and a lot of Sundays. It was a big treat for us. It is a lot of work because of all the ingredients that you have to layer on the pasta but it''s well worth it. You can choose whatever you like in the ziti, but we love it just like this. It''s filling and it''s good.', 2, 114, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Ziti', 'Ziti'),
('f508be48-aec6-4c02-8822-0c15317b1e92', 'mongolian-meatloaf-7aa41e', 'Mongolian Meatloaf', 'I could not be more pleased with how this Mongolian Meatloaf experiment turned out. Since I couldn''t decide whether to make meatloaf or Mongolian beef, I decided to try both things at once. The result is a tender meatloaf, sliced and crisped in a skillet and served with a sweet, salty, savory sauce, which, like the American Chinese restaurant favorite, Mongolian Beef, is not remotely Mongolian. But it sure is delicious, especially served over steamed rice with bok choy.', 3, 67, 2, ARRAY['오븐', '프라이팬', '칼']::text[], 'Comfort Food', 'Meatloaf'),
('88b607bd-639d-4c73-82af-f4283c8e74e1', 'philadelphia-style-roast-pork-sandwiches-2d25e0', 'Philadelphia-Style Roast Pork Sandwiches', 'Forget cheese steaks: this delicious roast pork sandwich is like the kind you''ll find in South Philly.', 2, 19, 2, ARRAY['오븐', '냄비', '프라이팬', '칼']::text[], 'Pork', 'Pork Sandwiches'),
('c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 'pretty-darn-quick-potato-gratin-5604f0', 'Pretty Darn Quick Potato Gratin', 'This cheesy potato gratin can be quickly prepped with a food processor.', 2, 44, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Easter', 'Potatoes Au Gratin'),
('95953cbf-395b-485f-8506-375c0ae0510d', 'pumpkin-baklava-76b0a6', 'Pumpkin Baklava', 'This recipe for pumpkin baklava is inspired by one that my aunt made from a recipe passed down to her from my yiayia (Greek for grandmother). I first made it with my aunt in Athens and finally recreated it at home. It''s a lesser known yet traditional version of Greek baklava.', 1, 57, 2, ARRAY['오븐', '냄비', '칼']::text[], 'Halloween', 'Pumpkin Recipes');
insert into public.recipe_translations (recipe_id, locale, name, description, category, subcategory) values
('469708f2-a8d3-43d4-8f27-a02935822037', 'en', 'Air Fryer Peanut Chicken', 'In this air fryer peanut chicken recipe, boneless, skinless chicken thighs are marinated in a spicy-sweet peanut marinade. Rice or noodles work with this dish, or cut it into bite-sized pieces and serve over a salad.', 'Air Fryer Recipes', 'Air Fryer Recipes'),
('469708f2-a8d3-43d4-8f27-a02935822037', 'ko', 'Air Fryer Peanut Chicken', 'In this air fryer peanut chicken recipe, boneless, skinless chicken thighs are marinated in a spicy-sweet peanut marinade. Rice or noodles work with this dish, or cut it into bite-sized pieces and serve over a salad.', 'Air Fryer Recipes', 'Air Fryer Recipes'),
('94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 'en', 'Loaded Cheeseburger Waffle Fry Bake', 'Waffle fries, ground beef, bacon, cheese combine in this easy bake reminiscent of a Cheeseburger.', 'Beef Recipes', 'Beef Recipes'),
('94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 'ko', 'Loaded Cheeseburger Waffle Fry Bake', 'Waffle fries, ground beef, bacon, cheese combine in this easy bake reminiscent of a Cheeseburger.', 'Beef Recipes', 'Beef Recipes'),
('95905e51-d14d-4651-893f-b8f09c0cb81f', 'en', 'Lyonnaise Potatoes', 'These Lyonnaise potatoes are a classic dish made with sliced potatoes and onions.', 'Healthy Recipes', 'Low-Sodium Recipes'),
('95905e51-d14d-4651-893f-b8f09c0cb81f', 'ko', 'Lyonnaise Potatoes', 'These Lyonnaise potatoes are a classic dish made with sliced potatoes and onions.', 'Healthy Recipes', 'Low-Sodium Recipes'),
('d24a9667-61c9-4802-8b8d-33c7b7a0fad7', 'en', 'Maria''s Portuguese Bacalau', 'This is a traditional Portuguese dish that brings back memories of mom. It is not only tasty but it is always a hit at parties. Plan ahead, because the salted cod (aka bacalhau or bacalao) needs to soak for 24 hours.', 'Casseroles', 'Seafood Casserole'),
('d24a9667-61c9-4802-8b8d-33c7b7a0fad7', 'ko', 'Maria''s Portuguese Bacalau', 'This is a traditional Portuguese dish that brings back memories of mom. It is not only tasty but it is always a hit at parties. Plan ahead, because the salted cod (aka bacalhau or bacalao) needs to soak for 24 hours.', 'Casseroles', 'Seafood Casserole'),
('cebef81f-9ad0-42ab-83de-3016327c779c', 'en', 'Peppers Stuffed with Grilled Chicken and Rice', 'Randomly threw a few things together one night with some chicken and the stuffed bell peppers turned out to be one of my husband''s favorite meals! I''m quite proud of it!', 'Main Dishes', 'Stuffed Bell Peppers'),
('cebef81f-9ad0-42ab-83de-3016327c779c', 'ko', 'Peppers Stuffed with Grilled Chicken and Rice', 'Randomly threw a few things together one night with some chicken and the stuffed bell peppers turned out to be one of my husband''s favorite meals! I''m quite proud of it!', 'Main Dishes', 'Stuffed Bell Peppers'),
('e2d84739-a6ee-4f0d-89df-7b167628c620', 'en', 'Scotch Eggs', 'Scotch eggs are soft-boiled eggs wrapped in sausage and bread crumbs, deep-fried for a delicious savory treat. They''re a British pub favorite, perfect for family occasions or picnics. We like to make these on Christmas Eve served on a bed of lettuce with sliced tomatoes and mustard for garnish.', 'Breakfast And Brunch', 'Breakfast And Brunch'),
('e2d84739-a6ee-4f0d-89df-7b167628c620', 'ko', 'Scotch Eggs', 'Scotch eggs are soft-boiled eggs wrapped in sausage and bread crumbs, deep-fried for a delicious savory treat. They''re a British pub favorite, perfect for family occasions or picnics. We like to make these on Christmas Eve served on a bed of lettuce with sliced tomatoes and mustard for garnish.', 'Breakfast And Brunch', 'Breakfast And Brunch'),
('f04b1e52-24a8-4f5b-8aad-35b17acf824d', 'en', 'Shepherd''s Pie', 'Make this shepherd''s pie with ground beef or lamb, carrots, and onions in a rich gravy. Top with a layer of cheesy mashed potato to satisfy even the pickiest of eaters. It''s a great way to sneak some extra veggies into dinner!', 'Beef Recipes', 'Beef Pie'),
('f04b1e52-24a8-4f5b-8aad-35b17acf824d', 'ko', 'Shepherd''s Pie', 'Make this shepherd''s pie with ground beef or lamb, carrots, and onions in a rich gravy. Top with a layer of cheesy mashed potato to satisfy even the pickiest of eaters. It''s a great way to sneak some extra veggies into dinner!', 'Beef Recipes', 'Beef Pie'),
('cd59422f-afa1-4644-8561-833a48b22296', 'en', 'Shrimp Tostadas', 'Salad, side, main dish, and bread all in a little stack? Yes, please! Make that two! The slaw, refried black beans, and shrimp stack up on crispy tostada shells for a fun and tasty dinner. If your family likes milder heat, use only one chipotle pepper, and omit the cayenne.', 'Mexican', 'Authentic Mexican Recipes'),
('cd59422f-afa1-4644-8561-833a48b22296', 'ko', 'Shrimp Tostadas', 'Salad, side, main dish, and bread all in a little stack? Yes, please! Make that two! The slaw, refried black beans, and shrimp stack up on crispy tostada shells for a fun and tasty dinner. If your family likes milder heat, use only one chipotle pepper, and omit the cayenne.', 'Mexican', 'Authentic Mexican Recipes'),
('deec6010-176c-445a-88c8-9e523639499b', 'en', 'Southeast Asian Style Chicken Rice', 'I''ve mixed elements of Vietnamese, Thai, Indonesian and other Asian cuisines to make a delicious chicken and rice dish topped with a fresh herb salad.', 'Cooking For Two', 'Cooking For Two'),
('deec6010-176c-445a-88c8-9e523639499b', 'ko', 'Southeast Asian Style Chicken Rice', 'I''ve mixed elements of Vietnamese, Thai, Indonesian and other Asian cuisines to make a delicious chicken and rice dish topped with a fresh herb salad.', 'Cooking For Two', 'Cooking For Two'),
('06689175-403c-4ac6-8f0a-f2ca327d5412', 'en', 'Black Bean Lasagna II', 'Lasagna with a Southwest twist. This can be frozen unbaked and kept for up to a month. Simply thaw in refrigerator overnight and bake as directed. Tastes even better reheated the second day!', 'Lasagna', 'Vegetarian Lasagna'),
('06689175-403c-4ac6-8f0a-f2ca327d5412', 'ko', 'Black Bean Lasagna II', 'Lasagna with a Southwest twist. This can be frozen unbaked and kept for up to a month. Simply thaw in refrigerator overnight and bake as directed. Tastes even better reheated the second day!', 'Lasagna', 'Vegetarian Lasagna'),
('9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 'en', 'Empanada Pie', 'Serve this empanada pie with a salad, hard-boiled eggs, salsa or sour cream, and shredded Mexican cheese (optional).', 'Empanadas', 'Empanadas'),
('9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 'ko', 'Empanada Pie', 'Serve this empanada pie with a salad, hard-boiled eggs, salsa or sour cream, and shredded Mexican cheese (optional).', 'Empanadas', 'Empanadas'),
('fccaa0bb-7114-4d7e-877b-d0c691236135', 'en', 'Air Fryer French Fries', 'This air fryer French fries recipe includes a cold water-hot water soaking trick that produces super crispy French fries. Made with just four ingredients, these fries rival traditional fries but use a fraction of the oil. Serve with burgers, steak, or chicken with something to dip them in, like honey mustard, spicy ketchup, or garlic aioli.', 'Air Fryer Recipes', 'Air Fryer Side Dish Recipes'),
('fccaa0bb-7114-4d7e-877b-d0c691236135', 'ko', 'Air Fryer French Fries', 'This air fryer French fries recipe includes a cold water-hot water soaking trick that produces super crispy French fries. Made with just four ingredients, these fries rival traditional fries but use a fraction of the oil. Serve with burgers, steak, or chicken with something to dip them in, like honey mustard, spicy ketchup, or garlic aioli.', 'Air Fryer Recipes', 'Air Fryer Side Dish Recipes'),
('30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 'en', 'Air Fryer Tostones', 'Tostones are made with green (unripe) plantains and are a very popular side dish in many Caribbean and South American countries. The traditional method is to twice-fry the plantains in oil, but this air-fried version of my Puerto Rican family''s recipe is much lighter as it uses olive oil spray instead of deep-frying.', 'Appetizers And Snacks', 'Fruit Appetizers'),
('30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 'ko', 'Air Fryer Tostones', 'Tostones are made with green (unripe) plantains and are a very popular side dish in many Caribbean and South American countries. The traditional method is to twice-fry the plantains in oil, but this air-fried version of my Puerto Rican family''s recipe is much lighter as it uses olive oil spray instead of deep-frying.', 'Appetizers And Snacks', 'Fruit Appetizers'),
('6bc9bf6c-af62-4164-869b-9afd70a52ca9', 'en', 'Authentic Tacos al Pastor', 'Tacos al pastor is a quintessential Mexican dish, with tender pork and pineapple marinated in a savory and aromatic chile sauce. Serve with warm corn tortillas, tomatillos salsa, and lemon or lime wedges.', 'Cooking For A Crowd', 'Cooking For A Crowd Main Dishes'),
('6bc9bf6c-af62-4164-869b-9afd70a52ca9', 'ko', 'Authentic Tacos al Pastor', 'Tacos al pastor is a quintessential Mexican dish, with tender pork and pineapple marinated in a savory and aromatic chile sauce. Serve with warm corn tortillas, tomatillos salsa, and lemon or lime wedges.', 'Cooking For A Crowd', 'Cooking For A Crowd Main Dishes'),
('87593681-0e4c-41e9-89d4-60038027a1b7', 'en', 'Bacon Jalapeño Popper Puffs', 'If you enjoy the gut bombs that are classic, bacon-wrapped, jalapeño poppers, I think you''ll love this recipe for shockingly light puffs. All the same flavors are there, especially when served with the easy cream cheese dip, and the prep is much easier.', 'July 4Th', '4Th Of July Appetizers'),
('87593681-0e4c-41e9-89d4-60038027a1b7', 'ko', 'Bacon Jalapeño Popper Puffs', 'If you enjoy the gut bombs that are classic, bacon-wrapped, jalapeño poppers, I think you''ll love this recipe for shockingly light puffs. All the same flavors are there, especially when served with the easy cream cheese dip, and the prep is much easier.', 'July 4Th', '4Th Of July Appetizers'),
('b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 'en', 'Baked Philly Cheesesteak Sliders', 'These baked cheesesteak sliders let you achieve something close to a proper Philly cheesesteak at home. Plus, the small rolls make me feel like a big man! Speaking of feeling like a giant, football season is upon us, and I can''t think of a better sandwich to make for your buddies coming over to watch the game.', 'Beef Recipes', 'Hamburgers'),
('b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 'ko', 'Baked Philly Cheesesteak Sliders', 'These baked cheesesteak sliders let you achieve something close to a proper Philly cheesesteak at home. Plus, the small rolls make me feel like a big man! Speaking of feeling like a giant, football season is upon us, and I can''t think of a better sandwich to make for your buddies coming over to watch the game.', 'Beef Recipes', 'Hamburgers'),
('c9c26bac-4f40-4181-8691-1414747c49dd', 'en', 'Baked Pumpkin Polenta', 'Chef John''s baked pumpkin polenta gives a savory pumpkin twist to polenta prepared in an interesting, visually appealing, baked form. It is so soft and creamy inside a crust that holds its shape, subtly sweet and earthy.', 'Chef John', 'Chef John''S Side Dishes'),
('c9c26bac-4f40-4181-8691-1414747c49dd', 'ko', 'Baked Pumpkin Polenta', 'Chef John''s baked pumpkin polenta gives a savory pumpkin twist to polenta prepared in an interesting, visually appealing, baked form. It is so soft and creamy inside a crust that holds its shape, subtly sweet and earthy.', 'Chef John', 'Chef John''S Side Dishes'),
('88e30023-5bb9-40cb-8124-d8e26dce3fc1', 'en', 'Beef Bourguignon I', 'This rich beef bourguignon smells incredible as it cooks and brings my teenaged boys running! Serve this hearty yet fancy dish with potatoes, noodles, or rice.', 'Beef Recipes', 'Beef Stew'),
('88e30023-5bb9-40cb-8124-d8e26dce3fc1', 'ko', 'Beef Bourguignon I', 'This rich beef bourguignon smells incredible as it cooks and brings my teenaged boys running! Serve this hearty yet fancy dish with potatoes, noodles, or rice.', 'Beef Recipes', 'Beef Stew'),
('12b23cd5-03eb-452e-8c9c-8db9839f6d78', 'en', 'Beef Pho', 'This beef pho features a comforting, richly-seasoned meat broth ladled over rice noodles and thinly sliced sirloin. Serve with hoisin, Sriracha, green onion, cilantro, bean sprouts, basil, and lime.', 'Beef Recipes', 'Veal Recipes'),
('12b23cd5-03eb-452e-8c9c-8db9839f6d78', 'ko', 'Beef Pho', 'This beef pho features a comforting, richly-seasoned meat broth ladled over rice noodles and thinly sliced sirloin. Serve with hoisin, Sriracha, green onion, cilantro, bean sprouts, basil, and lime.', 'Beef Recipes', 'Veal Recipes'),
('41518416-0bd8-465b-80a0-01f7cf6961dd', 'en', 'Beef Tenderloin With Roasted Shallots', 'The shallot sauce takes some time, but is well worth the trouble. This is definitely a company dish, and the recipe doubles well for a larger party. Serve with a green salad and roasted vegetables.', 'Beef Recipes', 'Beef Short Loin'),
('41518416-0bd8-465b-80a0-01f7cf6961dd', 'ko', 'Beef Tenderloin With Roasted Shallots', 'The shallot sauce takes some time, but is well worth the trouble. This is definitely a company dish, and the recipe doubles well for a larger party. Serve with a green salad and roasted vegetables.', 'Beef Recipes', 'Beef Short Loin'),
('8f14fb9c-6aef-4b36-8665-03c0792363f0', 'en', 'Beet, Orange, and Apple Salad', 'This beet and orange salad is a nice, colorful salad. Wedges of cooked beets, sliced apples, and orange sections are dressed with a delicious vinaigrette and spooned onto a bed of shredded beet greens.', 'Easter', 'Easter Salads'),
('8f14fb9c-6aef-4b36-8665-03c0792363f0', 'ko', 'Beet, Orange, and Apple Salad', 'This beet and orange salad is a nice, colorful salad. Wedges of cooked beets, sliced apples, and orange sections are dressed with a delicious vinaigrette and spooned onto a bed of shredded beet greens.', 'Easter', 'Easter Salads'),
('014759da-9af1-4725-8279-9d4d85540b04', 'en', 'Brown Butter Carrot Sheet Cake with Brown Butter-Cream Cheese Frosting', 'This carrot cake not only feeds a crowd, but it also gets an extra delicious flavor from the addition of brown butter to both the cake and the frosting. Top cake with candied carrot slices and toasted finely chopped walnuts, if desired.', 'Cakes', 'Carrot Cake'),
('014759da-9af1-4725-8279-9d4d85540b04', 'ko', 'Brown Butter Carrot Sheet Cake with Brown Butter-Cream Cheese Frosting', 'This carrot cake not only feeds a crowd, but it also gets an extra delicious flavor from the addition of brown butter to both the cake and the frosting. Top cake with candied carrot slices and toasted finely chopped walnuts, if desired.', 'Cakes', 'Carrot Cake'),
('f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 'en', 'Bruschetta Chicken Pasta Salad', 'Summertime is the perfect time for all things pasta salad and grilling related. This bruschetta chicken pasta salad is bursting with flavor and topped with vibrant colorful tomatoes.', 'Pasta Salads', 'Pasta Salads'),
('f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 'ko', 'Bruschetta Chicken Pasta Salad', 'Summertime is the perfect time for all things pasta salad and grilling related. This bruschetta chicken pasta salad is bursting with flavor and topped with vibrant colorful tomatoes.', 'Pasta Salads', 'Pasta Salads'),
('fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 'en', 'Buffalo Chicken Wings in a Jar', 'This fun-sized take on the game day appetizer offers everything you love about Buffalo wings, minus the bones, messy frying, and any risk of your drunk friends dripping sauce all over the place. Instead of wings, we simply take chicken thighs, simmer them directly in butter ''n hot sauce, shred, and mix with celery. The blue cheese comes in the accompanying crostini: baguette slices toasted and spread with butter and blue cheese.', 'Buffalo Chicken Wings', 'Buffalo Chicken Wings'),
('fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 'ko', 'Buffalo Chicken Wings in a Jar', 'This fun-sized take on the game day appetizer offers everything you love about Buffalo wings, minus the bones, messy frying, and any risk of your drunk friends dripping sauce all over the place. Instead of wings, we simply take chicken thighs, simmer them directly in butter ''n hot sauce, shred, and mix with celery. The blue cheese comes in the accompanying crostini: baguette slices toasted and spread with butter and blue cheese.', 'Buffalo Chicken Wings', 'Buffalo Chicken Wings'),
('f26e0fdf-d47b-432e-8968-06e0f002aa31', 'en', 'Chicageaux Spicy Smokehouse Tots', 'These tater tots are loaded with saucy, spicy chicken, cheese, and queso blanco. We kept it spicy for the great folks at Frank''s Red Hot.', 'Casseroles', 'Chicken Casserole'),
('f26e0fdf-d47b-432e-8968-06e0f002aa31', 'ko', 'Chicageaux Spicy Smokehouse Tots', 'These tater tots are loaded with saucy, spicy chicken, cheese, and queso blanco. We kept it spicy for the great folks at Frank''s Red Hot.', 'Casseroles', 'Chicken Casserole'),
('dff0c484-1553-4f0a-8803-68da4c42d4f7', 'en', 'Chopped Liver the Real Mccoy', 'No recipe site is complete without a real recipe for real chopped liver. This makes for a great appetizer or spread for a pastrami and corned beef sandwich.', 'Hanukkah', 'Hanukkah Appetizers'),
('dff0c484-1553-4f0a-8803-68da4c42d4f7', 'ko', 'Chopped Liver the Real Mccoy', 'No recipe site is complete without a real recipe for real chopped liver. This makes for a great appetizer or spread for a pastrami and corned beef sandwich.', 'Hanukkah', 'Hanukkah Appetizers'),
('982abbc8-08d6-4c65-8738-df00d4b9fc13', 'en', 'Chorizo Queso Potato Bombs', 'Try these chorizo queso potato bombs if you feel like trying out something new. The perfect appetizer, they are crunchy on the outside and rich and creamy on the inside.', 'Appetizers And Snacks', 'Cheese Appetizers'),
('982abbc8-08d6-4c65-8738-df00d4b9fc13', 'ko', 'Chorizo Queso Potato Bombs', 'Try these chorizo queso potato bombs if you feel like trying out something new. The perfect appetizer, they are crunchy on the outside and rich and creamy on the inside.', 'Appetizers And Snacks', 'Cheese Appetizers'),
('dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 'en', 'Classic Beef Empanadas', 'This authentic empanada recipe is for Argentinian beef empanadas filled with a savory and delicious mixture of ground beef, hard-cooked eggs, green olives, and potatoes. These classic empanadas are ubiquitous all over Argentina.', 'Appetizers And Snacks', 'Pastry Appetizers'),
('dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 'ko', 'Classic Beef Empanadas', 'This authentic empanada recipe is for Argentinian beef empanadas filled with a savory and delicious mixture of ground beef, hard-cooked eggs, green olives, and potatoes. These classic empanadas are ubiquitous all over Argentina.', 'Appetizers And Snacks', 'Pastry Appetizers'),
('c84f6946-ce78-4367-89c8-0abc7603546f', 'en', 'Comforting Scalloped Potatoes', 'Spread warm wishes and full bellies with this delightful dish from Amber Wilson of For The Love Of The South', 'Easter', 'Scalloped Potatoes'),
('c84f6946-ce78-4367-89c8-0abc7603546f', 'ko', 'Comforting Scalloped Potatoes', 'Spread warm wishes and full bellies with this delightful dish from Amber Wilson of For The Love Of The South', 'Easter', 'Scalloped Potatoes'),
('e4c8851a-192a-40a8-800b-6a29cb1a36d4', 'en', 'Copycat Chicken Fritta', 'This copycat chicken fritta features juicy fried chicken cutlets with a delicate, lightly crisp Asiago and breadcrumb crust, served over fettuccine in a luxurious, creamy Asiago cheese sauce. You''ll love this homemade version of the Olive Garden favorite.', 'Italian', 'Italian'),
('e4c8851a-192a-40a8-800b-6a29cb1a36d4', 'ko', 'Copycat Chicken Fritta', 'This copycat chicken fritta features juicy fried chicken cutlets with a delicate, lightly crisp Asiago and breadcrumb crust, served over fettuccine in a luxurious, creamy Asiago cheese sauce. You''ll love this homemade version of the Olive Garden favorite.', 'Italian', 'Italian'),
('eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 'en', 'Crispy Turnip "Fries"', 'Delicious crispy turnip "fries." My daughters and I are on a low-carb diet and were looking for something to curb our French fry cravings. I''ve heard that turnips can be made into some great fries. I experimented with it and came up with this. You can add whatever spices you''d like.', 'Low Calorie', 'Low-Calorie Side Dishes'),
('eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 'ko', 'Crispy Turnip "Fries"', 'Delicious crispy turnip "fries." My daughters and I are on a low-carb diet and were looking for something to curb our French fry cravings. I''ve heard that turnips can be made into some great fries. I experimented with it and came up with this. You can add whatever spices you''d like.', 'Low Calorie', 'Low-Calorie Side Dishes'),
('8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 'en', 'Decadent Cinnamon Roll Peach Cobbler', 'This peach cobbler is easy to make and very decadent. The use of store-bought cinnamon rolls makes it even faster to make. Serve with vanilla ice cream, if desired.', 'Cobblers', 'Peach Cobbler'),
('8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 'ko', 'Decadent Cinnamon Roll Peach Cobbler', 'This peach cobbler is easy to make and very decadent. The use of store-bought cinnamon rolls makes it even faster to make. Serve with vanilla ice cream, if desired.', 'Cobblers', 'Peach Cobbler'),
('0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 'en', 'Easy Baked Falafel with Cucumber-Yogurt Sauce', 'Try this Middle Eastern sandwich of chickpea and spice ''meatballs,'' which are actually falafel that are oven-fried to keep their calorie count down. Serve with grilled pita wedges or pita pockets, diced tomatoes, shredded lettuce, and cucumber slices.', 'Falafel', 'Falafel'),
('0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 'ko', 'Easy Baked Falafel with Cucumber-Yogurt Sauce', 'Try this Middle Eastern sandwich of chickpea and spice ''meatballs,'' which are actually falafel that are oven-fried to keep their calorie count down. Serve with grilled pita wedges or pita pockets, diced tomatoes, shredded lettuce, and cucumber slices.', 'Falafel', 'Falafel'),
('30437522-da47-49c9-8b17-065100b09ff8', 'en', 'Eggplant Rollatini', 'After having a delicious eggplant rollatini at an Italian restaurant, I decided I just had to learn how to make it! Hope you enjoy my recipe.', 'Main Dishes', 'Fall Main Dishes'),
('30437522-da47-49c9-8b17-065100b09ff8', 'ko', 'Eggplant Rollatini', 'After having a delicious eggplant rollatini at an Italian restaurant, I decided I just had to learn how to make it! Hope you enjoy my recipe.', 'Main Dishes', 'Fall Main Dishes'),
('3d5e8391-0b20-4f86-8de8-2f47b0f17658', 'en', 'Homemade Gluten-Free Gnocchi', 'This gluten-free gnocchi tastes like potatoes with a bouncy texture, even without gluten. This recipe uses a trick from the past when Italian cooks would toss potatoes into a fire or oven that was being cooled down so as not to waste the heat. Surplus baked potatoes became gnocchi because they have very little moisture (the secret to firm gnocchi) and they have a roasted potato flavor which is delicious!', 'Dumplings', 'Dumplings'),
('3d5e8391-0b20-4f86-8de8-2f47b0f17658', 'ko', 'Homemade Gluten-Free Gnocchi', 'This gluten-free gnocchi tastes like potatoes with a bouncy texture, even without gluten. This recipe uses a trick from the past when Italian cooks would toss potatoes into a fire or oven that was being cooled down so as not to waste the heat. Surplus baked potatoes became gnocchi because they have very little moisture (the secret to firm gnocchi) and they have a roasted potato flavor which is delicious!', 'Dumplings', 'Dumplings'),
('00f3ed38-4474-4722-8d75-845db3662157', 'en', 'Hot Bean and Bacon Dip with Air Fryer Tortilla Chips', 'This is a great dip for game day, potlucks, or get-togethers. We serve it with air-fried tortilla chips. Leftovers are great (but you probably won''t have any) in a flour tortilla for a bean and cheese burrito, or roll it in a corn tortilla for a quick taco.', 'Nachos', 'Nachos'),
('00f3ed38-4474-4722-8d75-845db3662157', 'ko', 'Hot Bean and Bacon Dip with Air Fryer Tortilla Chips', 'This is a great dip for game day, potlucks, or get-togethers. We serve it with air-fried tortilla chips. Leftovers are great (but you probably won''t have any) in a flour tortilla for a bean and cheese burrito, or roll it in a corn tortilla for a quick taco.', 'Nachos', 'Nachos'),
('608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 'en', 'Hychin', 'Hychin is a traditional dish of the Balkar people, from the Caucasus mountains in Russia (Elbrus region). These flatbreads with a cheese and potato filling are traditionally cooked in a cast-iron skillet and served with garlic and dill sauce on the side.', 'Breads', 'Flat Bread'),
('608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 'ko', 'Hychin', 'Hychin is a traditional dish of the Balkar people, from the Caucasus mountains in Russia (Elbrus region). These flatbreads with a cheese and potato filling are traditionally cooked in a cast-iron skillet and served with garlic and dill sauce on the side.', 'Breads', 'Flat Bread'),
('98da70d7-b8a7-42b5-88ab-c8c000c0796b', 'en', 'I Tried Giada''s Sheet Pan Lasagna Method and am Never Going Back', 'This spinach and artichoke sheet pan lasagna, inspired by Giada''s viral recipe, is loaded with sausage, spinach, and artichokes. It''s cheesy, golden, and bubbly, with all of the lasagna goodness you expect, but the assembly is much simpler.', 'Dinner', 'Sheet Pan Dinners'),
('98da70d7-b8a7-42b5-88ab-c8c000c0796b', 'ko', 'I Tried Giada''s Sheet Pan Lasagna Method and am Never Going Back', 'This spinach and artichoke sheet pan lasagna, inspired by Giada''s viral recipe, is loaded with sausage, spinach, and artichokes. It''s cheesy, golden, and bubbly, with all of the lasagna goodness you expect, but the assembly is much simpler.', 'Dinner', 'Sheet Pan Dinners'),
('3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 'en', 'Jalapeño Bacon Cheddar Deviled Eggs', 'This jalapeño bacon Cheddar deviled eggs recipe is a spin on an old classic — deviled eggs with the addition of savory bacon, delicious Cheddar, and spicy jalapeño.', 'Appetizers And Snacks', 'Deviled Eggs'),
('3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 'ko', 'Jalapeño Bacon Cheddar Deviled Eggs', 'This jalapeño bacon Cheddar deviled eggs recipe is a spin on an old classic — deviled eggs with the addition of savory bacon, delicious Cheddar, and spicy jalapeño.', 'Appetizers And Snacks', 'Deviled Eggs'),
('9ad6f83e-c441-4a91-84ce-3c3475373cf0', 'en', 'Joy''s Green Banana Salad', 'A recipe from my kitchen when I was in Puerto Rico made with green bananas, sweet onion and bacon in a vinegar dressing. I have served it to my North American friends and they love it as well. It is great to serve instead of the same ol'' potato salad. Dare to try something new?', 'Fruit Salads', 'Fruit Salads'),
('9ad6f83e-c441-4a91-84ce-3c3475373cf0', 'ko', 'Joy''s Green Banana Salad', 'A recipe from my kitchen when I was in Puerto Rico made with green bananas, sweet onion and bacon in a vinegar dressing. I have served it to my North American friends and they love it as well. It is great to serve instead of the same ol'' potato salad. Dare to try something new?', 'Fruit Salads', 'Fruit Salads'),
('a7da003c-4ec6-433a-817a-2007ed13e26b', 'en', 'Lemon Chicken Piccata', 'This delicious chicken piccata dish is exquisite and easy to prepare. The light and luscious lemon sauce really pops without being too acidic; it is simply divine. I love to serve this with herb-roasted potatoes or lemon-rice pilaf.', 'Mother''S Day', 'Mother''S Day'),
('a7da003c-4ec6-433a-817a-2007ed13e26b', 'ko', 'Lemon Chicken Piccata', 'This delicious chicken piccata dish is exquisite and easy to prepare. The light and luscious lemon sauce really pops without being too acidic; it is simply divine. I love to serve this with herb-roasted potatoes or lemon-rice pilaf.', 'Mother''S Day', 'Mother''S Day'),
('68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 'en', 'Mashed Potato au Gratin', 'This spectacular mashed potato au gratin is my favorite potato side dish, mashed potatoes, topped with my other favorite potato side dish, potatoes au gratin. Beautiful, buttery mashed potatoes, with crusty, cheesy potatoes on top—it''s a whole new exciting way to eat potatoes.', 'Chef John', 'Chef John''S Side Dishes'),
('68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 'ko', 'Mashed Potato au Gratin', 'This spectacular mashed potato au gratin is my favorite potato side dish, mashed potatoes, topped with my other favorite potato side dish, potatoes au gratin. Beautiful, buttery mashed potatoes, with crusty, cheesy potatoes on top—it''s a whole new exciting way to eat potatoes.', 'Chef John', 'Chef John''S Side Dishes'),
('ee4c8735-2376-41a2-816a-d0184aaf437d', 'en', 'Mediterranean Casserole', 'Whether you''re on a diet or just like to eat Italian cooking with flavor, this is the perfect choice for you. In Italy it is usually served after an entree, but can also be eaten as a main dish with a tossed salad.', 'Casseroles', 'Seafood Casserole'),
('ee4c8735-2376-41a2-816a-d0184aaf437d', 'ko', 'Mediterranean Casserole', 'Whether you''re on a diet or just like to eat Italian cooking with flavor, this is the perfect choice for you. In Italy it is usually served after an entree, but can also be eaten as a main dish with a tossed salad.', 'Casseroles', 'Seafood Casserole'),
('80640f12-2148-4b50-8637-f83a257d54e5', 'en', 'Melanzane alla Parmigiana (Eggplant Parmesan)', 'Melanzane alla parmigiana is a classic Italian dish from Sicily that''s often simply referred to as "parmigiana" by Sicilian locals. The richness and depth of flavor you get from this authentic version is well worth the extra effort. Serve eggplant Parmesan with nothing more than crusty bread and a green salad.', 'Eggplant Parmesan', 'Eggplant Parmesan'),
('80640f12-2148-4b50-8637-f83a257d54e5', 'ko', 'Melanzane alla Parmigiana (Eggplant Parmesan)', 'Melanzane alla parmigiana is a classic Italian dish from Sicily that''s often simply referred to as "parmigiana" by Sicilian locals. The richness and depth of flavor you get from this authentic version is well worth the extra effort. Serve eggplant Parmesan with nothing more than crusty bread and a green salad.', 'Eggplant Parmesan', 'Eggplant Parmesan'),
('228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 'en', 'Mini Philly Cheesesteaks', 'Miniaturized sandwiches don''t usually float my boat, as they''re almost always not as good as the full-sized versions. But this mini Philly cheesesteak recipe captures everything I love about the classic.', 'Appetizers And Snacks', 'Canapes And Crostini'),
('228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 'ko', 'Mini Philly Cheesesteaks', 'Miniaturized sandwiches don''t usually float my boat, as they''re almost always not as good as the full-sized versions. But this mini Philly cheesesteak recipe captures everything I love about the classic.', 'Appetizers And Snacks', 'Canapes And Crostini'),
('bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 'en', 'Mom''s Pasta al Forno', 'Mom used to make this pasta al forno on special days, like on holidays and a lot of Sundays. It was a big treat for us. It is a lot of work because of all the ingredients that you have to layer on the pasta but it''s well worth it. You can choose whatever you like in the ziti, but we love it just like this. It''s filling and it''s good.', 'Ziti', 'Ziti'),
('bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 'ko', 'Mom''s Pasta al Forno', 'Mom used to make this pasta al forno on special days, like on holidays and a lot of Sundays. It was a big treat for us. It is a lot of work because of all the ingredients that you have to layer on the pasta but it''s well worth it. You can choose whatever you like in the ziti, but we love it just like this. It''s filling and it''s good.', 'Ziti', 'Ziti'),
('f508be48-aec6-4c02-8822-0c15317b1e92', 'en', 'Mongolian Meatloaf', 'I could not be more pleased with how this Mongolian Meatloaf experiment turned out. Since I couldn''t decide whether to make meatloaf or Mongolian beef, I decided to try both things at once. The result is a tender meatloaf, sliced and crisped in a skillet and served with a sweet, salty, savory sauce, which, like the American Chinese restaurant favorite, Mongolian Beef, is not remotely Mongolian. But it sure is delicious, especially served over steamed rice with bok choy.', 'Comfort Food', 'Meatloaf'),
('f508be48-aec6-4c02-8822-0c15317b1e92', 'ko', 'Mongolian Meatloaf', 'I could not be more pleased with how this Mongolian Meatloaf experiment turned out. Since I couldn''t decide whether to make meatloaf or Mongolian beef, I decided to try both things at once. The result is a tender meatloaf, sliced and crisped in a skillet and served with a sweet, salty, savory sauce, which, like the American Chinese restaurant favorite, Mongolian Beef, is not remotely Mongolian. But it sure is delicious, especially served over steamed rice with bok choy.', 'Comfort Food', 'Meatloaf'),
('88b607bd-639d-4c73-82af-f4283c8e74e1', 'en', 'Philadelphia-Style Roast Pork Sandwiches', 'Forget cheese steaks: this delicious roast pork sandwich is like the kind you''ll find in South Philly.', 'Pork', 'Pork Sandwiches'),
('88b607bd-639d-4c73-82af-f4283c8e74e1', 'ko', 'Philadelphia-Style Roast Pork Sandwiches', 'Forget cheese steaks: this delicious roast pork sandwich is like the kind you''ll find in South Philly.', 'Pork', 'Pork Sandwiches'),
('c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 'en', 'Pretty Darn Quick Potato Gratin', 'This cheesy potato gratin can be quickly prepped with a food processor.', 'Easter', 'Potatoes Au Gratin'),
('c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 'ko', 'Pretty Darn Quick Potato Gratin', 'This cheesy potato gratin can be quickly prepped with a food processor.', 'Easter', 'Potatoes Au Gratin'),
('95953cbf-395b-485f-8506-375c0ae0510d', 'en', 'Pumpkin Baklava', 'This recipe for pumpkin baklava is inspired by one that my aunt made from a recipe passed down to her from my yiayia (Greek for grandmother). I first made it with my aunt in Athens and finally recreated it at home. It''s a lesser known yet traditional version of Greek baklava.', 'Halloween', 'Pumpkin Recipes'),
('95953cbf-395b-485f-8506-375c0ae0510d', 'ko', 'Pumpkin Baklava', 'This recipe for pumpkin baklava is inspired by one that my aunt made from a recipe passed down to her from my yiayia (Greek for grandmother). I first made it with my aunt in Athens and finally recreated it at home. It''s a lesser known yet traditional version of Greek baklava.', 'Halloween', 'Pumpkin Recipes');
insert into public.recipe_steps (id, recipe_id, step_number, instruction) values
('6e17967c-c8cb-4028-88bd-638daf26df64', '469708f2-a8d3-43d4-8f27-a02935822037', 1, 'Combine chili sauce, soy sauce, Sriracha, lime zest, lime juice, granulated garlic, minced ginger, peanut butter, and salt to taste in a large resealable plastic bag. Gently move and mash the ingredients inside the bag until well blended.'),
('8300f948-7f2f-47ed-8c98-c7c2b85a36bc', '469708f2-a8d3-43d4-8f27-a02935822037', 2, 'Add chicken to the bag, and squeeze out as much air as possible. Move chicken around inside the bag until each piece is coated in marinade. Marinate in the refrigerator for at least 30 minutes and up to 24 hours.'),
('45dbad4f-e7e1-4f2f-8730-9fa721d3d574', '469708f2-a8d3-43d4-8f27-a02935822037', 3, 'Preheat an air fryer to 350 degrees F (180 degrees C), or according to manufacturer''s recommendations.'),
('7882ceff-68e5-4150-854f-ee2347b36181', '469708f2-a8d3-43d4-8f27-a02935822037', 4, 'Spray the cooking surface of the air fryer with cooking spray.'),
('0ad417f8-9258-47b7-8aee-0b110b2225b4', '469708f2-a8d3-43d4-8f27-a02935822037', 5, 'Take chicken pieces from the bag, and allow the marinade to drip back into the bag. Place chicken pieces in the air fryer in a single layer and air fry for 20 to 22 minutes, turning halfway through, until an instant-read thermometer inserted near the center reads 165 degrees F (74 degrees C).'),
('9296d22a-4465-4937-875e-5d6f57ee189a', '469708f2-a8d3-43d4-8f27-a02935822037', 6, 'Meanwhile, add about 1/2 cup of water to the unused marinade, and mix contents; pour into a microwave-safe container. Microwave on High, until marinade comes to a boil, and cook about 1 minute longer; watch carefully to see it does not boil over.'),
('4218c721-f27b-43c6-891c-d3b63248d59f', '469708f2-a8d3-43d4-8f27-a02935822037', 7, 'Serve chicken over rice, with sauce on the side as a dip. Garnish with chopped cilantro, sliced scallions, julienne cucumbers and carrots, and chopped peanuts, as desired.'),
('dc1c19c1-f75e-495d-8ea5-d5f782fc3dfe', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 1, 'Place bacon in a large skillet and cook over medium-high heat, turning occasionally, until evenly browned, about 10 minutes. Drain bacon slices on paper towels. Once cool enough to handle, roughly chop.'),
('8cf2c7b4-3280-46e8-8d71-ac4199852f7b', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 2, 'Meanwhile, preheat an air fryer oven to 400 degrees F (200 degrees C).'),
('3c3c21b1-cb37-451e-88ee-99da3052e0dc', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 3, 'Air fry the waffle fries until golden and crispy, shaking halfway through, for 8 to 10 minutes or bake as directed on the package. Be sure to flip the half way through baking.'),
('c66383b7-a2cf-4147-8c33-d7e388041692', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 4, 'Preheat the oven to 375 degrees F (190 degrees C).'),
('3ce64a46-9af2-4c7a-8f9e-d85ead5c5055', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 5, 'Heat olive oil in a large skillet over medium heat. Add onions and cook until softened, 2 to 3 minutes. Add minced garlic and cook until fragrant, about 30 seconds. Add ground beef and season with salt and pepper. Cook and stir ground beef in the hot skillet until browned and crumbly, breaking up any clumps as it cooks, 5 to 7 minutes. Drain and discard grease. Stir in ketchup, mustard, and mayonnaise to completely coat the beef mixture. Simmer for 1 to 2 minutes.'),
('b5a6889e-00b5-4095-8055-2af1c3413a63', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 6, 'Preheat the oven to 375 degrees C (190 degrees C).'),
('2d694261-125e-4ce3-8910-e9449de53f24', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 7, 'Spread cooked beef mixture evenly into a 9x13-inch baking dish. Sprinkle Cheddar cheese on top and arrange crispy waffle fries in an even layer over the cheese. Sprinkle mozzarella over waffle fries, followed by chopped bacon.'),
('197f339f-95d9-4909-80c3-4dd7f289ee55', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 8, 'Bake casserole in the preheated oven just until cheese is melted and casserole is heated through, about 5 minutes.'),
('51be16cc-175a-40c4-8c63-d87e146a3549', '94dd3ed7-c003-4446-850b-b6cf4e7e63b6', 9, 'Top with chopped pickles and diced tomatoes, and additional ketchup and mustard for an extra special cheeseburger flavor. Serve immediately while the waffle fries are still crispy!'),
('67e035ec-039b-4443-8700-33240506c39f', '95905e51-d14d-4651-893f-b8f09c0cb81f', 1, 'Preheat the oven to 400 degrees F (200 degrees C).'),
('cf467399-f55f-49e4-8734-a8b87c1043a7', '95905e51-d14d-4651-893f-b8f09c0cb81f', 2, 'Peel potatoes and cut them into 1/2-inch slices. Place in a pot and cover with water; bring to a boil. Boil for 2 minutes, then drain and set aside.'),
('7b864d85-5cea-4dc7-8837-934c59fb68c4', '95905e51-d14d-4651-893f-b8f09c0cb81f', 3, 'Heat a large oven-proof skillet over medium-high heat. Pour in olive oil, then add onions. Sauté until lightly caramelized, 8 to 10 minutes. Stir in garlic and sauté until onions are deep brown and garlic is soft. Transfer mixture to a bowl.'),
('0f2d2122-3462-41e6-84c7-c69b229a0246', '95905e51-d14d-4651-893f-b8f09c0cb81f', 4, 'Place the skillet back on the stove over low heat. Melt butter in the skillet, then cover the bottom with 1/3 of the potatoes. Season with salt and pepper. Cover potatoes with 1/2 of the onion mixture. Cover with 1/2 of the remaining potatoes; season with salt and pepper. Spread remaining onion mixture on top. Cover with remaining potatoes; season with salt and pepper.'),
('e0ade299-d885-4481-8307-c14994dad132', '95905e51-d14d-4651-893f-b8f09c0cb81f', 5, 'Bake in the preheated oven until potatoes are tender and browned on top, 10 to 12 minutes.'),
('b30e029e-f5cb-44a5-8596-197e3fb4c3ec', '95905e51-d14d-4651-893f-b8f09c0cb81f', 6, 'Use a spatula to transfer potatoes to a serving platter. Sprinkle with chopped parsley just before serving.'),
('ff69f0f7-ab78-444e-8bbf-4c28d8368458', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 1, 'Soak dried salted cod in cold water for 24 hours, changing the water several times.'),
('ca26443e-fb0b-4c8b-895d-25136515014c', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 2, 'Bring a large pot of water to a boil. Add soaked cod; boil until flakes easily with a fork, about 5 minutes. Transfer cod to a cutting board; save water for cooking potatoes. Remove cod skin and bones then flake the meat into pieces using a fork; set aside in a large bowl.'),
('d35efff7-5fdd-49af-863f-c13ecc1ab637', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 3, 'Whisk olive oil, 1 tablespoon parsley, 1 clove garlic, pepper flakes, and black pepper together in a small bowl; pour over cod and lightly toss to coat.'),
('5ec38ea2-1641-40e9-8d45-7d02c35437d1', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 4, 'Preheat the oven to 350 degrees F (175 degrees C). Grease an 8x11-inch baking dish.'),
('ea0c9419-6716-4afe-8796-691e19b97768', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 5, 'Place potatoes in reserved pot salt cod cooking water; bring to a boil. Cook until tender, about 20 minutes. Drain under cool water, peel, and cut into 1/4-inch slices.'),
('c399b156-f8bb-4c83-8775-5dcd4aad7b95', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 6, 'While potatoes cook, melt butter in a large skillet over medium heat. Add onions; sauté until golden and caramelized. Stir in remaining 1 clove garlic; set aside.'),
('a8cd9f98-c3b9-4c6a-8a36-e22107bf1587', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 7, 'Layer 1/2 of the potatoes in the bottom of the prepared baking dish; cover with 1/2 of the cod, then 1/2 of the onions. Repeat layers, ending with onions.'),
('8250f82f-b442-4b9b-83bd-e4fb3197f71e', 'd24a9667-61c9-4802-8b8d-33c7b7a0fad7', 8, 'Bake in the preheated oven until lightly browned, about 15 minutes. Garnish with olives and hard-cooked eggs; sprinkle with remaining 7 tablespoons parsley.'),
('1544425e-28bb-4b4c-8893-42206af866f0', 'cebef81f-9ad0-42ab-83de-3016327c779c', 1, 'Preheat the oven to 375 degrees F (190 degrees C). Place green peppers in a baking dish with 1/8 cup water in the bottom.'),
('87c7a370-4eb7-44e1-8ff7-59e3b588cec3', 'cebef81f-9ad0-42ab-83de-3016327c779c', 2, 'Bake in the preheated oven until peppers are slightly browned around the edges, 20 to 25 minutes.'),
('951cd2bd-24da-4930-8cc9-71383d6058d1', 'cebef81f-9ad0-42ab-83de-3016327c779c', 3, 'While the peppers are baking, whisk 1/4 cup water and 2 tablespoons taco seasoning together in a small bowl. Add chicken and toss to coat. Cover the bowl with plastic wrap and marinate in the refrigerator for at least 15 minutes.'),
('7d3d502e-6271-4235-8f9c-fddf307067c4', 'cebef81f-9ad0-42ab-83de-3016327c779c', 4, 'Combine remaining 1 cup water and rice in a pot over high heat; bring to a boil. Cover, reduce heat to low, and cook for 15 minutes. Remove from the heat. Stir in remaining taco seasoning and let sit, covered, until tender, about 15 minutes more. Remove the lid, drain any remaining liquid, and set aside.'),
('9434ed57-612a-4d4b-81ca-6fc4dff5ff65', 'cebef81f-9ad0-42ab-83de-3016327c779c', 5, 'Preheat an outdoor grill for medium heat and lightly oil the grate.'),
('5af34424-4c7e-481a-842a-26fc4e284881', 'cebef81f-9ad0-42ab-83de-3016327c779c', 6, 'Remove chicken from the refrigerator and place on the preheated grill with the pepper slices. Cook chicken until no longer pink in the center and the juices run clear, about 5 to 7 minutes per side. An instant-read thermometer inserted into the center of the chicken should read at least 165 degrees F (74 degrees C). Grill peppers until tender, about 2 to 3 minutes per side.'),
('bfd5c1a1-d6fc-475b-8b59-01554a2897a9', 'cebef81f-9ad0-42ab-83de-3016327c779c', 7, 'Remove chicken and peppers from the grill and allow to cool. Shred chicken and dice peppers.'),
('351089cc-59c5-4443-80c5-ca34775005ce', 'cebef81f-9ad0-42ab-83de-3016327c779c', 8, 'Heat oil in a large skillet over medium heat. Add onions and garlic; saute until soft, 5 to 7 minutes. Add cooked rice, shredded chicken, diced peppers, diced tomatoes and green chiles, 1/2 of the cheese, and garlic salt; stir until well blended. Cook over medium heat, stirring occasionally, until hot, about 5 minutes.'),
('0397fc7f-e4f2-48e8-8581-fd2660f6b9ca', 'cebef81f-9ad0-42ab-83de-3016327c779c', 9, 'Spoon rice mixture into the green peppers. Top with remaining cheese.'),
('dc171ea6-f812-4e6b-8e18-e205b3900d6b', 'cebef81f-9ad0-42ab-83de-3016327c779c', 10, 'Return to the oven until cheese is melted, about 5 minutes.'),
('913b6e14-5124-4db1-8b4a-20c29b44d497', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 1, 'Gather all ingredients. Preheat the oven to 350 degrees F (175 degrees C). Heat oil in a deep-fryer to 375 degrees F (190 degrees C).'),
('1d28bf79-10d0-4495-829f-2768f98eb62a', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 2, 'Place eggs in a saucepan and cover with water. Bring to boil. Cover, remove from heat, and let eggs sit in hot water for 10 to 12 minutes. Remove from hot water, cool, and peel.'),
('5f26e8ee-073e-46af-80cd-cf005cd015bb', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 3, 'Flatten sausage and make a patty to surround each egg.'),
('ea06a6a3-e945-4211-8695-315e6687f554', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 4, 'Very lightly flour the outer sausage layer then coat with beaten egg. Roll in bread crumbs to cover evenly.'),
('7bb00f11-a79b-4fbb-80a3-0dc268ee5732', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 5, 'Deep-fry prepared eggs in hot oil until golden brown while making sure each side is well cooked.'),
('99d7d2de-addf-43a9-8a72-c1c9d59f1386', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 6, 'Bake in the preheated oven for 10 minutes.'),
('aa3b102a-d8db-40a2-8b4e-389b20ab7f03', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 7, 'Cut in half and serve.'),
('6b39cccf-7d63-4c23-89ba-77303e24cd1c', 'e2d84739-a6ee-4f0d-89df-7b167628c620', 8, 'Enjoy!'),
('d32f3147-0568-4c0d-8c57-1faba2b565d0', 'f04b1e52-24a8-4f5b-8aad-35b17acf824d', 1, 'Gather all ingredients.'),
('70e3c921-d2f1-4b47-891a-d799cc690802', 'f04b1e52-24a8-4f5b-8aad-35b17acf824d', 2, 'Bring a large pot of salted water to a boil. Add potatoes and cook until tender but still firm, about 15 minutes. Drain and mash. Mix in butter, finely chopped onion and 1/4 cup shredded cheese. Season with salt and pepper to taste; set aside.'),
('9f23497d-39d7-460d-81da-87c0e2c26775', 'f04b1e52-24a8-4f5b-8aad-35b17acf824d', 3, 'Bring a large pot of salted water to a boil. Add carrots and cook until tender but still firm, about 15 minutes. Drain, mash and set aside. Preheat oven to 375 degrees F (190 degrees C.)'),
('8de755ee-f70c-4c8e-8151-85f2736d9e47', 'f04b1e52-24a8-4f5b-8aad-35b17acf824d', 4, 'Heat oil in a large frying pan. Add onion and cook until clear. Add ground beef and cook until well browned. Pour off excess fat, then stir in flour and cook 1 minute. Add ketchup and beef broth. Bring to a boil, reduce heat and simmer for 5 minutes.'),
('b279a464-8300-42e7-8752-c744c68a9114', 'f04b1e52-24a8-4f5b-8aad-35b17acf824d', 5, 'Spread the ground beef in an even layer on the bottom of a 2 quart casserole dish. Next, spread a layer of mashed carrots. Top with the mashed potato mixture and sprinkle with remaining shredded cheese.'),
('77498866-f6f1-4d77-8bd5-e1178044242c', 'f04b1e52-24a8-4f5b-8aad-35b17acf824d', 6, 'Bake in the preheated oven for 20 minutes, or until golden brown. Serve hot and enjoy!'),
('b7ddafd3-89c6-45ad-8f45-9e54c9c4a0c4', 'cd59422f-afa1-4644-8561-833a48b22296', 1, 'Combine mayonnaise, minced chipotle peppers, lime juice, honey, avocado oil, 1 teaspoon cumin, and salt to taste for the slaw in a large bowl. Stir until well blended. Add shredded cabbage and toss to coat. Refrigerate until ready to use.'),
('c0c08b2c-5f50-4e3b-833d-c47562b411d8', 'cd59422f-afa1-4644-8561-833a48b22296', 2, 'Combine water, sofrito base, and cayenne pepper in a large skillet for the slaw. Bring to a boil over medium heat. Add shrimp to the boiling liquid, bring back to a boil, and cook until shrimp turn white and peachy-pink, and make a "C" shape, 3 to 5 minutes. Using a slotted spoon or spider, remove shrimp from the cooking liquid immediately.'),
('96223cf2-a67a-4d55-81dd-8312ee6b6716', 'cd59422f-afa1-4644-8561-833a48b22296', 3, 'Set an oven rack about 6 inches from the heat source and preheat the broiler. Line a baking tray with aluminum foil.'),
('3dad20a6-67fd-45fc-8b15-19c263066275', 'cd59422f-afa1-4644-8561-833a48b22296', 4, 'Stir refried beans, smoked paprika, 1/2 teaspoon cumin, and garlic granules together in a bowl for the tostadas. Spread each tostada shell with bean mixture, 1 to 2 tablespoons per tostada, or to taste. Sprinkle queso fresco crumbles evenly on each tostada. Place tostadas on the prepared baking tray in a single layer.'),
('9de52996-0a24-4e61-8e93-32f4dfb2ea0b', 'cd59422f-afa1-4644-8561-833a48b22296', 5, 'Broil under the preheated broiler until cheese begins to melt, 1 to 2 minutes. Watch that tostada shells do not burn.'),
('2b42c47e-1bd3-461b-89b9-e73add1591c2', 'cd59422f-afa1-4644-8561-833a48b22296', 6, 'Place about 1/2 cup of the prepared slaw on each tostada. Top with chopped cilantro to taste. Add three shrimp per tostada, and drizzle crema over all. Serve with lime slices, if desired.'),
('6aa57482-cb39-4993-85ab-68e32b272217', 'deec6010-176c-445a-88c8-9e523639499b', 1, 'Set chicken breast onto a cutting board and make 5 or 6 shallow cuts through the skin. Season generously on both sides with salt.'),
('b4417009-52f7-4706-8fa5-68a1619818b8', 'deec6010-176c-445a-88c8-9e523639499b', 2, 'Heat vegetable oil in a skillet over medium high heat and sear chicken breast, skin-side down, until the skin is golden brown and fat has rendered out, about 5 minutes. Flip breast over, and keep cooking until chicken is cooked through, about 5 minutes more. If oil starts to smoke before the chicken is cooked, reduce heat to medium or medium-low.'),
('9fc75d61-a492-4f39-8b5c-ab5d0ba6707b', 'deec6010-176c-445a-88c8-9e523639499b', 3, 'Turn off the heat and transfer chicken to a plate to rest until cool enough to handle. Peel off the skin and finely chop. Refrigerate chicken breast.'),
('f6e0a928-5575-4d12-8c1d-50c176a0a1fb', 'deec6010-176c-445a-88c8-9e523639499b', 4, 'Add minced chicken skin back into the skillet over and medium heat. Cook and stir until the skin browns and starts getting crisp, 3 to 5 minutes. Add ginger, garlic, and onions and cook, stirring, until onions start to turn translucent, about 5 minutes. Add turmeric and rice; cook and stir until rice is well coated with oil, 2 to 3 minutes.'),
('a5cf052b-f4ec-4d84-84d0-6c54a47286b2', 'deec6010-176c-445a-88c8-9e523639499b', 5, 'Stir in broth, turn heat to high, and bring to a boil. Cover, reduce heat to low, and simmer undisturbed for 20 minutes. Turn off the heat and set a timer for 10 minutes to allow rice to rest.'),
('5dd6030f-cccd-4dcd-847d-5ee1f8bdf9b0', 'deec6010-176c-445a-88c8-9e523639499b', 6, 'Meanwhile, shred the chicken meat using your hands or cut into small pieces. Place into a bowl. Add red onion, green onions, Fresno chili, lime juice, soy sauce, hot sauce, sesame oil, salt, pepper, fresh mint and cilantro. Toss until well combined. Taste and adjust with more lime juice, salt, and/or spice as needed.'),
('a7766e50-3841-4932-8b20-ab1b6e541107', 'deec6010-176c-445a-88c8-9e523639499b', 7, 'After the 10 minute rice timer is up, remove cover, and fluff rice with a fork. Taste and adjust seasoning if necessary. Serve rice topped with the chicken herb salad mixture and lime wedges.'),
('6ae44d2a-6b7c-485d-8820-33d768ad63a0', '06689175-403c-4ac6-8f0a-f2ca327d5412', 1, 'Preheat oven to 350 degrees F (175 degrees C). Bring a large pot of lightly salted water to a boil. Add pasta and cook for 8 to 10 minutes or until al dente; drain.'),
('c6a4ec5c-78a7-4de1-8725-ec2ff3cb1015', '06689175-403c-4ac6-8f0a-f2ca327d5412', 2, 'Coat a large skillet with non-stick cooking spray, and place over medium heat. Saute onion, red bell pepper, corn and garlic until tender. Stir in black beans, refried beans, tomato sauce, salsa and 1/4 cup cilantro. Cook until heated through and slightly thickened; set aside.'),
('91a2c4b1-2105-424c-8d9d-ea1c583ca537', '06689175-403c-4ac6-8f0a-f2ca327d5412', 3, 'In a large bowl, combine cottage cheese, ricotta, sour cream, shredded Monterey Jack cheese and remaining 1/4 cup chopped cilantro; set aside.'),
('05b9efe9-d27c-425d-8ccd-4adcd7688e64', '06689175-403c-4ac6-8f0a-f2ca327d5412', 4, 'Coat a 9x13 inch casserole dish with non-stick cooking spray. Arrange 3 of the cooked lasagna noodles in the bottom of the dish, cutting to fit if necessary. Spread with 1/3 of the bean mixture, then 1/3 of the cheese mixture. Repeat layers twice more.'),
('a6dc788e-c5b2-4dc5-8c90-9b8e66dd4233', '06689175-403c-4ac6-8f0a-f2ca327d5412', 5, 'Cover, and bake in preheated oven for 45 minutes. Garnish with sliced black olives and sprigs of cilantro.'),
('ff98ec21-6560-440c-8291-976c9eb09a17', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 1, 'Place onion in a food processor and process to a medium chop. Use a garlic press to add garlic to the chopped onion.'),
('e29457fa-3ee4-483d-83ba-9372f7e2bc9b', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 2, 'Preheat a saute pan over medium-high heat. Add oil, onion, and garlic to the hot pan. Reduce heat to medium and saute until golden, about 5 minutes.'),
('94b95c3a-ef94-4f5f-86ea-d32911acea52', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 3, 'Place mushrooms in the food processor and process to a medium dice. Stir into the onion mixture and cook for 3 to 4 minutes. Meanwhile, process olives to a fine mince and set aside.'),
('bd71fce6-6f0e-4647-8e53-4c03861d5831', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 4, 'Add oregano, paprika, cumin, red pepper flakes, and pepper to the pan; cook and stir until fragrant, 1 to 2 minutes. Crumble in ground beef and cook, breaking up with a spoon or spatula, until thoroughly browned, 5 to 8 minutes. Stir in olives. Remove from heat and cool for 20 to 30 minutes, stirring occasionally.'),
('848535bb-5781-4acd-8870-a39a4d72b82f', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 5, 'Preheat the oven to 425 degrees F (220 degrees C). Spray a 9-inch pie plate with cooking spray. Line the plate with 1 pie crust.'),
('e2fef6d2-7b02-40fe-8ac4-47c8595f8777', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 6, 'Carefully spoon the cooled beef mixture into the crust. Press the second crust on top. Slice air vents in the top crust.'),
('2c7fa895-4119-4eae-8fb8-47aa04e547ca', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 7, 'Beat egg and water together in a small bowl. Brush egg wash thoroughly over the complete surface of the pie.'),
('9f829e10-b615-4a12-86c8-8eb61f26aebe', '9aeea0a3-1dd5-4ed5-8afb-a5e90422a52b', 8, 'Bake in the preheated oven until crust is golden brown, 45 to 50 minutes. Let cool for 5 to 10 minutes before cutting and serving.'),
('b4577802-d64c-4804-8bb0-12b24e7f84cb', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 1, 'Gather all ingredients.'),
('9f230881-0a7c-4511-88ee-cbd0e718be82', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 2, 'Cut each potato lengthwise into 3/8-inch-thick slices, then slice sections into 3/8-inch-wide sticks. Place potatoes in a bowl of cold water. Let soak to release excess starches, about 5 minutes; drain.'),
('31128ad0-be9c-4265-8c89-b7e9e7c52577', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 3, 'Pour boiling water over the potatoes until they''re covered by a few inches. Let sit for 10 minutes. Drain potatoes and transfer onto some paper towels. Blot off excess water and let cool completely, at least 10 minutes.'),
('0e08b18d-72e4-48fb-826b-734caa68d8fa', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 4, 'Place cooled potatoes in a mixing bowl. Drizzle with oil and season with cayenne; toss to coat.'),
('332618c7-1653-4a5e-8cf2-984a41ba4781', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 5, 'Preheat an air fryer to 375 degrees F (190 degrees C).'),
('8fdd18c2-cb99-4610-8b43-ae1485aec036', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 6, 'Stack potatoes in a double layer in the fryer basket.'),
('98571f72-3e07-45a6-8b1b-28a3c7067e30', 'fccaa0bb-7114-4d7e-877b-d0c691236135', 7, 'Cook for 15 minutes. Slide basket out and toss fries. Continue frying until golden brown, about 10 minutes more. Toss fries with salt in a mixing bowl. Serve immediately.'),
('5d63043e-1e2e-48bb-8e23-d5b52ca4a3e1', '30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 1, 'Preheat an air fryer to 400 degrees F (200 degrees C).'),
('b20049d4-bb94-427d-8695-3a19a1d009aa', '30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 2, 'Slice tips off the plantain. Make a vertical cut in the skin from end to end, making sure to cut only through the thick skin and not into the plantain flesh. Cut plantain, still with the peel, into 1-inch chunks. Peel the skin off each chunk starting at the slit you made.'),
('45e8d096-5148-46a9-82d7-e4030fa19a59', '30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 3, 'Place the plantain chunks in your air fryer basket and spray them with olive oil spray. Air fry for 5 minutes. Meanwhile, prepare a bowl of salted water.'),
('e26dc844-120c-4c27-836f-35fcc867bc03', '30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 4, 'Remove the plantain pieces from the air fryer with tongs. Smash to about 1/2-inch thickness using a tostonera (plantain smasher). Soak the smashed tostones in the bowl of salted water while smashing the rest.'),
('bf645baa-abb9-43ee-85a9-0adf94acd6dd', '30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 5, 'Remove the tostones from the salted water and pat dry with a paper towel.'),
('4bfea9fb-87ff-4450-836a-1fe8193c65d3', '30eecfcf-e974-4ccd-814a-ddec9b0d7b3f', 6, 'Return tostones to the air fryer in batches, filling the basket with a single layer each time. Spray the tops with olive oil spray and season with salt; air fry for 5 minutes. Flip with tongs and spray the other side with olive oil spray. Season with salt. Air fry until golden brown and crisp, 4 to 5 minutes more.'),
('ca466275-5dcd-4976-8679-600970775238', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 1, 'Cook tomato on a ridged grill pan over medium-high heat until slightly blackened, about 5 minutes. Remove from heat and cool until easily handled. Peel off skin and remove seeds.'),
('236e117c-0173-41e3-8497-b51cbca41c19', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 2, 'Bring a small pot of water to a boil. Add guajillo and ancho chile peppers; cook until softened, about 5 minutes. Drain.'),
('ffd0f876-ff84-48d9-861e-6e7695cd30fa', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 3, 'Combine tomato flesh, softened chile peppers, 2 slices pineapple, orange juice, quartered onion, vinegar, chipotle peppers, salt, garlic, cloves, cumin seeds, and oregano in a blender; blend until smooth.'),
('c0d89aa0-e7dc-4a77-82c9-fbffb62bf4b0', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 4, 'Arrange pork slices in a glass or ceramic baking dish. Pour blended mixture over pork, ensuring all sides are evenly coated. Cover baking dish with plastic wrap.'),
('9573f28d-ce3e-4293-8d05-a355b8b26180', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 5, 'Marinate pork in the refrigerator, 4 hours to overnight.'),
('b3538b51-2667-4d66-87ca-583433b1441d', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 6, 'Cook remaining pineapple slices on a ridged grill pan over medium-high heat until slightly blackened and soft, about 5 minutes per side. Chop into small pieces.'),
('1df481d3-6147-469e-8187-d0b8f8eb7244', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 7, 'Wipe out grill pan and preheat over medium-high heat. Cook marinated pork in the hot pan, turning once, until browned, 4 to 5 minutes.'),
('b45fec06-4fdf-4e9c-8271-c3a7579d4863', '6bc9bf6c-af62-4164-869b-9afd70a52ca9', 8, 'Chop pork coarsely into small pieces against the grain. Serve with pineapple, chopped onion, and cilantro.'),
('0e2f6524-8b8f-4bcb-88c4-1258084f578c', '87593681-0e4c-41e9-89d4-60038027a1b7', 1, 'Make the dipping sauce: Mix cream cheese, crème fraîche, green onions, and lime juice together in a bowl. If mixture seems too thick, add enough water to thin it to your preferred consistency.'),
('2e6fb90a-0c7a-4c74-848c-d99044b7a9bf', '87593681-0e4c-41e9-89d4-60038027a1b7', 2, 'Make the puffs: Place bacon in a large skillet and cook over medium-high heat, turning occasionally, until evenly browned and crisp, about 10 minutes. Drain bacon slices on paper towels. Crumble or finely chop. Drain fat from skillet, reserving 1 tablespoon.'),
('d3921277-fd4a-4124-85ed-24aa8604638f', '87593681-0e4c-41e9-89d4-60038027a1b7', 3, 'Place skillet over medium-high heat. Add cold water, butter, reserved bacon fat, and salt. Bring mixture to a simmer; reduce heat to medium. Pour in flour all at once. Stir to mix and mash with a wooden spoon until dough starts to pull together, 2 to 3 minutes. Remove pan from heat; transfer dough to a mixing bowl and let cool for about 5 minutes.'),
('be4c6ff6-02d7-4727-8059-1b1747996a43', '87593681-0e4c-41e9-89d4-60038027a1b7', 4, 'When dough is cool, whisk in 1 egg. Mixture will separate slightly. Continue whisking in first egg until mixture pulls back together. Repeat with the second egg. Scrape down sides of bowl. Add diced jalapeño, bacon pieces, shredded cheese, cayenne pepper, and black pepper. Mix thoroughly with a spatula. Wrap dough in plastic wrap and refrigerate until cool, 30 minutes to 1 hour.'),
('ece53e12-17f9-4511-8bf3-cdc9728adf57', '87593681-0e4c-41e9-89d4-60038027a1b7', 5, 'Heat oil in a deep fryer to 375 degrees F (190 degrees C).'),
('11defba1-c9d5-4fa9-8648-36ea93929cec', '87593681-0e4c-41e9-89d4-60038027a1b7', 6, 'Using a small scoop, scoop out rounds of dough. Drop rounds of dough into hot oil and cook until golden brown and cooked through, 3 to 4 minutes. Work in batches if necessary. Transfer to a cooling rack.'),
('0d4528f2-c005-47b8-8325-7b306afcc72c', '87593681-0e4c-41e9-89d4-60038027a1b7', 7, 'Serve with dipping sauce garnished with a few green onion slices.'),
('0b2a8ae0-f3a2-46bc-80a4-3da01c47d295', 'b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 1, 'Heat olive oil in a large skillet over medium-high heat. Season steaks generously with salt, black pepper, and cayenne. Cook steaks in hot oil for 5 to 6 minutes. Flip and add onions around steaks. Continue cooking until steaks begin to firm and are hot and slightly pink in the center, 5 to 6 minutes more. Push onions under steaks and cook until browned but still crunchy, 2 to 3 minutes more. Remove steaks and sautéed onions to a plate.'),
('d4fcd256-ccea-4e52-8ddc-dd1db65a69f2', 'b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 2, 'Preheat the oven to 425 degrees F (220 degrees C). Line a baking tray with aluminum foil.'),
('805e007d-6d18-443a-80c7-1deed9c26d75', 'b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 3, 'Place rolls on the prepared baking tray. Hollow out the top of each roll by cutting in at a 45-degree angle. Pinch off some of the bread inside to make room for the filling.'),
('17196c49-a19c-4108-81b1-a27553bd955f', 'b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 4, 'Slice steaks into thin strips, then across into 1/2-inch pieces. Transfer to a mixing bowl. Add sautéed onions and accumulated meat juices. Toss in 1 ½ cups provolone, pickled peppers, cream cheese, 1 teaspoon kosher salt, and 1/4 teaspoon black pepper; mix until thoroughly combined. Taste and season with salt if needed. Spoon filling into rolls and top with remaining 1 cup provolone cheese.'),
('7af0d447-1767-4704-8e2c-18df9d692267', 'b0f3e6c9-9cd3-495e-81dc-8a126aa3944e', 5, 'Bake in the preheated oven until cheese is melted and the edges of rolls start to brown, about 15 minutes.'),
('fd76e3cb-e623-466f-8f45-43073159f64a', 'c9c26bac-4f40-4181-8691-1414747c49dd', 1, 'Add olive oil to a saucepan set over medium-high heat; add butter, and heat until melted. Toss in sage leaves and fry until they are dark green and have stopped bubbling, 20 to 30 seconds. Turn off the heat; remove sage leaves to a paper towel-lined plate and set aside. Fried sage leaves can be stored in the refrigerator and used to garnish the tops later.'),
('6408e1fe-f1f3-45ce-8cf2-a54f2c0128a3', 'c9c26bac-4f40-4181-8691-1414747c49dd', 2, 'Add pumpkin to the pan, pour in water, and turn heat to high. Whisk and bring to a boil. Season with salt and pepper.'),
('5661de9d-c4b7-45c1-8d2b-3d26e2eee219', 'c9c26bac-4f40-4181-8691-1414747c49dd', 3, 'With mixture boiling, slowly sprinkle in cornmeal, whisking constantly. Reduce heat to medium-low, and cook, stirring occasionally, until cornmeal is creamy, soft, and no longer gritty, about 25 minutes.'),
('4798343b-91ee-475e-813d-8722c41d6373', 'c9c26bac-4f40-4181-8691-1414747c49dd', 4, 'Turn off heat; add cayenne, milk, and Parmigiano Reggiano cheese. Whisk thoroughly until evenly combined.'),
('c7a681be-4131-47a6-817d-ea9aa235a2c9', 'c9c26bac-4f40-4181-8691-1414747c49dd', 5, 'Generously grease a 9x9-inch cake pan with olive oil; spread polenta evenly into the pan. Let cool to room temperature. Wrap and chill in the refrigerator for at least 3 hours.'),
('bd437db7-9a78-4b83-8dc6-778f1b447352', 'c9c26bac-4f40-4181-8691-1414747c49dd', 6, 'Preheat the oven to 425 degrees F (220 degrees C). Invert cold, firm polenta onto a cutting board and cut into 8 equal portions.'),
('21fa37ab-b250-4a26-8241-7f67180f2d93', 'c9c26bac-4f40-4181-8691-1414747c49dd', 7, 'Transfer to a lined baking sheet, and top each piece with grated Monterey Jack cheese. Sprinkle tops with paprika or cayenne, if desired.'),
('5d5f3085-d0c5-4c55-80d6-95897e247550', 'c9c26bac-4f40-4181-8691-1414747c49dd', 8, 'Bake in the preheated oven until polenta is heated through, and the edges are turning golden-brown, about 30 minutes. Garnish tops with fried sage and serve.'),
('d3c92daf-3934-4dd3-8e33-77aca681aa70', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 1, 'For the marinade: Mix wine, sliced onions, carrots, brandy, garlic, peppercorns, salt, parsley, and bay leaf in a large glass or ceramic bowl. Add beef and toss to evenly coat; cover the bowl with plastic wrap and marinate in the refrigerator for 2 days.'),
('46218ffc-8fa5-49b8-8372-8d8ed3ecde7f', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 2, 'For the bourguignon: Preheat the oven to 300 degrees F (150 degrees C).'),
('1a87d115-e038-405c-826d-b6f592e084fa', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 3, 'Strain beef from the marinade and shake off excess; pat dry with paper towels. Strain vegetables and set aside; reserve marinade. Heat 2 tablespoons of oil in a large skillet over medium-high heat. Add beef in batches; cook until browned on all sides. Transfer browned beef into a separate medium bowl; set aside.'),
('120b3506-dff1-4691-8baf-54a6864e18a5', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 4, 'Add bacon to the same skillet; cook and stir until lightly browned. Transfer bacon to the bowl with browned beef. Drain the skillet and return it to the heat. Pour 1 cup of reserved marinade into the skillet; bring to a boil while scraping the browned bits of food off the bottom of the pan with a wooden spoon. Return this liquid to the reserved marinade.'),
('c01d825c-4c4e-4c6a-8b70-38c3ea2e48f1', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 5, 'Heat remaining 2 tablespoons oil in the same skillet. Add chopped onions; cook and stir until just tender, about 2 to 3 minutes. Stir in reserved onions and carrots from the marinade; mix well, then use a slotted spoon to transfer vegetables into the bowl with beef.'),
('32cb98e0-4c71-458e-8551-ca3ba426b305', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 6, 'Return the skillet to the heat; stir flour in pan drippings until browned, about 1 or 2 minutes. Stir in garlic and tomato paste until combined. Add beef broth, remaining reserved marinade, salt, and pepper. Bring to a boil, whisking to remove any flour lumps; pour over beef mixture in the bowl. Transfer beef mixture into a casserole or baking dish.'),
('024cfbb4-deb8-465e-8f37-84243c6f0f62', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 7, 'Cook in the preheated oven until beef is tender, about 3 hours; stir occasionally and add water if needed.'),
('d27e39aa-b085-46c2-821e-227050b5dd63', '88e30023-5bb9-40cb-8124-d8e26dce3fc1', 8, 'About 10 minutes before serving, melt butter in a skillet over medium-high heat. Add mushrooms and sauté until lightly browned, about 5 to 7 minutes; stir mushrooms into beef mixture until well combined.'),
('07567627-f757-45a2-8cec-a5ab3b64c324', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 1, 'Gather all ingredients.'),
('02624faa-65fd-443c-8f37-ac1e747b115d', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 2, 'Make broth: Place beef bones in a 9-quart (or larger) pot; season with 1 teaspoon salt. Pour water into the pot and bring to a boil. Reduce heat and simmer broth for about 2 hours.'),
('81550103-dd55-40d6-8556-ca85eabdcf56', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 3, 'Meanwhile, set an oven rack about 6 inches from the heat source and preheat the oven''s broiler. Line a 10x15-inch roasting pan with aluminum foil.'),
('8418d2ca-f53f-473a-8509-3992ef6be512', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 4, 'Place onions and unpeeled ginger onto the prepared roasting pan and cook under the preheated broiler, stirring occasionally, until vegetables are charred, 10 to 15 minutes.'),
('b1f7fb5d-bc5d-4fa5-869c-d9754ebc7ba8', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 5, 'Cool slightly. Chop onions, then peel and slice ginger; set aside separately.'),
('afb55809-d7f0-470d-8a7f-0a2354c0d7be', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 6, 'Skim fat from surface of simmering broth. Add oxtail, radish, and charred onions to broth. Tie charred ginger, anise, cinnamon stick, peppercorns, and cloves in cheesecloth to make a bouquet garni; add to broth. Stir in sugar, fish sauce, and remaining 2 teaspoons salt. Simmer over medium-low heat for at least 4 hours (the longer, the better). Season with salt.'),
('815fd231-aded-4048-86b8-7aa721c7318d', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 7, 'Strain broth. Discard bones and bouquet garni. Reserve meat from bones for another use. Chill broth in the refrigerator, 8 hours to overnight.'),
('9023c6a3-bac5-4da7-8cb1-57e10f7cd202', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 8, 'Skim and discard fat from the top of chilled broth. Pour broth into a pot; bring to a boil. Reduce heat and keep hot until ready to serve.'),
('5879d574-de7f-4d07-825c-4f62c8f80063', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 9, 'Bring a pot of water to a boil. Turn off heat. Stir in rice noodles and let sit until noodles are tender yet chewy, 6 to 10 minutes.'),
('8ad5e9c1-c5a8-4c1a-85aa-0d10bc2bb975', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 10, 'Meanwhile, cut frozen sirloin into paper-thin slices.'),
('f7b2f32d-21de-477a-8ed1-958c1198e1e4', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 11, 'Drain and divide noodles among bowls, about 1 1/2 cups per serving. Top each with a few sirloin slices. Ladle hot broth over sirloin and noodles.'),
('86a2019a-7080-4276-899b-730dcc21d6bf', '12b23cd5-03eb-452e-8c9c-8db9839f6d78', 12, 'Serve and enjoy!'),
('ed52b449-cc99-407a-8b4d-7f62c298289d', '41518416-0bd8-465b-80a0-01f7cf6961dd', 1, 'Preheat oven to 375 degrees F (190 degrees C). In 9 inch pie pan, toss shallots with oil to coat. Season with salt and pepper. Roast until shallots are deep brown and very tender, stirring occasionally, about 30 minutes.'),
('b4abdde7-4944-4fc3-8b2c-129f7699ce7d', '41518416-0bd8-465b-80a0-01f7cf6961dd', 2, 'In a large saucepan, combine beef broth and port. Bring to a boil. Cook over high heat until the volume is reduced by half, about 30 minutes. Whisk in tomato paste. Set aside.'),
('b5795bc9-cb30-4864-847e-e7705329ae1e', '41518416-0bd8-465b-80a0-01f7cf6961dd', 3, 'Pat beef dry; sprinkle with thyme, salt and pepper. In a large roasting pan, set over medium heat on the stove top, saute bacon until golden. Using a slotted spoon, transfer bacon to paper towels. Add beef to pan; brown on all sides over medium high heat, about 7 minutes.'),
('09188b6d-bc41-4c14-85f6-b9a480aa1fe4', '41518416-0bd8-465b-80a0-01f7cf6961dd', 4, 'Transfer pan to oven. Roast beef until meat thermometer inserted into center registers 125 degrees F (50 degrees C) for medium rare, about 25 minutes. Transfer beef to platter. Tent loosely with foil.'),
('4a41d496-e67c-4f90-8f6d-1d049a7a694f', '41518416-0bd8-465b-80a0-01f7cf6961dd', 5, 'Spoon fat off top of pan drippings in roasting pan. Place pan over high heat on stove top. Add broth mixture, and bring to boil; stir to scrape up any browned bits. Transfer to a medium saucepan, and bring to simmer. Mix 1 1/2 tablespoon butter and flour in small bowl to form smooth paste; whisk into broth mixture, and simmer until sauce thickens. Whisk in remaining butter. Stir in roasted shallots and reserved bacon. Season with salt and pepper.'),
('f51eeb31-a2cf-4586-89a0-bc3788b2acad', '41518416-0bd8-465b-80a0-01f7cf6961dd', 6, 'Cut beef into 1/2 inch thick slices. Spoon some sauce over, and garnish with watercress.'),
('99a7b1c9-7855-455a-8f71-03b7c188e3ad', '8f14fb9c-6aef-4b36-8665-03c0792363f0', 1, 'Wash and dry beets and greens. Shred greens to measure 2 cups and set aside.'),
('172b47f3-929f-4561-8470-06e521ab3967', '8f14fb9c-6aef-4b36-8665-03c0792363f0', 2, 'Place beets in a sauce pan with enough water to cover. Bring to a boil, cover, reduce heat and simmer for 20 minutes or until tender. Drain and allow to cool.'),
('50725297-9ebe-4b24-82b4-735cb013d42a', '8f14fb9c-6aef-4b36-8665-03c0792363f0', 3, 'Trim and peel skins off beets; cut into 8 wedges.'),
('0bb1494b-9cf1-4473-8e6b-a48d67e6b9a2', '8f14fb9c-6aef-4b36-8665-03c0792363f0', 4, 'Combine orange sections, beets, and apples in a bowl.'),
('070c610e-a9f2-4820-856c-16bed36d9a6a', '8f14fb9c-6aef-4b36-8665-03c0792363f0', 5, 'Whisk olive oil, vinegar, sugar, salt and garlic together in a bowl; pour over beet mixture and toss well.'),
('b23a9598-923c-4934-839f-cd48c261e775', '8f14fb9c-6aef-4b36-8665-03c0792363f0', 6, 'Arrange 1/2 cup beet greens on 4 salad plates. Top with beet mixture, sprinkle with sunflower seeds and serve.'),
('72a1f9b4-e327-45e4-8eb7-b1971d56f369', '014759da-9af1-4725-8279-9d4d85540b04', 1, 'Place butter in a light-colored saucepan over medium heat. Cook, swirling the pan constantly, until butter is bubbling, smells nutty, and browned bits begin to form on the bottom of the pan, 5 to 10 minutes. Immediately remove from heat and pour butter into a heat-safe bowl. Allow brown butter to cool to room temperature, about 15 minutes.'),
('e42e2bfb-ee26-43c2-880f-309ede51dd1f', '014759da-9af1-4725-8279-9d4d85540b04', 2, 'Preheat the oven to 325 degrees F (165 degrees C). Grease a 12x16-inch pan and line with parchment paper.'),
('7215ea12-0aa7-4040-8936-e7cf3336e958', '014759da-9af1-4725-8279-9d4d85540b04', 3, 'Whisk flour, baking soda, baking powder, cinnamon, allspice, nutmeg, and salt together in a bowl until well combined.'),
('ddda2607-e729-4766-8f9f-51d285dd8da7', '014759da-9af1-4725-8279-9d4d85540b04', 4, 'Beat cooled brown butter and brown sugar in a large bowl with an electric mixer on medium speed until well combined. Beat in eggs, one at a time, mixing well after each addition, until mixture is light and fluffy. Mix in vanilla. Pour in 1/2 of the flour mixture and mix until just combined. Add in remaining flour mixture and mix until just combined.'),
('c0c1db8d-fd6e-4fcb-8dbb-caf3b0fd22b7', '014759da-9af1-4725-8279-9d4d85540b04', 5, 'Fold in shredded carrots, walnuts, and raisins. Pour batter into the prepared pan and smooth out the top with a spatula.'),
('a1db18c7-735c-475b-86cf-f08b3acbeb7d', '014759da-9af1-4725-8279-9d4d85540b04', 6, 'Bake in the preheated oven until cake is golden and a toothpick inserted into the center of it comes out clean, 23 to 27 minutes. Transfer onto a wire rack and cool completely, about 30 minutes.'),
('d8bccec6-b54b-46fe-8935-259b6787a27b', '014759da-9af1-4725-8279-9d4d85540b04', 7, 'While cake is cooling, repeat step 1 to brown butter for the frosting. Let cool to room temperature, about 15 minutes.'),
('7843b9bd-d963-4d92-81a2-4fa27258be0c', '014759da-9af1-4725-8279-9d4d85540b04', 8, 'Beat cream cheese in a large bowl with an electric mixer on medium-high speed until completely smooth. Add in cooled brown butter and mix until thoroughly combined. Mix in powdered sugar, 1 cup at a time, beating well after each addition. Mix in vanilla and salt. Beat frosting at medium-high speed until completely smooth, 1 to 2 minutes.'),
('f98b4558-909a-479f-8051-6ff2ba4914b4', '014759da-9af1-4725-8279-9d4d85540b04', 9, 'Spread frosting over the cooled cake. Chill cake until ready to serve.'),
('4c6df3b6-853b-44b6-84e0-faaeff3b571e', 'f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 1, 'Place a chicken breast on a flat work surface. Slice horizontally through the middle, being careful not to cut all the way through to the other side. Open the 2 sides and spread them out like an open book. Repeat with remaining chicken breasts. Add chicken and vinaigrette to a resealable plastic bag; seal the bag and place in the refrigerator to marinate overnight.'),
('ae0a8fb3-ab79-418a-823f-9a478142317a', 'f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 2, 'Preheat an outdoor grill to 400 degrees F (200 degrees C).'),
('089b464c-36b1-4f2d-87c8-3a3d9748a370', 'f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 3, 'Discard vinaigrette, and place chicken on the grill. Grill for 4 to 5 minutes. Turn chicken breast over with tongs. Continue to cook until juices no longer run pink, and an instant-read thermometer reads 165 degrees F (74 degrees C), 4 to 5 minutes more.'),
('94e1099f-99e8-4c09-81e2-b2641e082256', 'f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 4, 'Meanwhile, bring a large pot of lightly salted water to a boil. Cook fusilli in the boiling water, stirring occasionally, until tender yet firm to the bite, about 12 minutes. Drain pasta and immediately submerge pasta in an ice water bath.'),
('a70713f6-fd49-4ba8-8e61-feb0f1dafdd9', 'f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 5, 'Cut tomatoes in half and place in a bowl. Add oil, minced garlic, and basil. Season to taste with salt and pepper.'),
('ae47de0c-8a27-45dd-8c5b-e0b2e46a3125', 'f9dc5d54-76ab-4fec-8afb-ca928e67fb90', 6, 'Drain pasta again; add to tomato mixture. Lightly toss to distribute tomatoes and combine. Top with grilled chicken breast, and drizzle with balsamic glaze.'),
('eed6b044-174a-474f-88cb-619d94c6020b', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 1, 'Heat a dry saucepan over high heat. Place thighs skin-side down in the hot pan and cook until skin is browned, seasoning generously with salt, about 5 minutes. Turn thighs over once skin no longer sticks to the pan. Add butter, Louisiana hot sauce, and water. Toss thighs around to stir the sauce until butter is melted.'),
('ba9211e1-d0f1-499b-8b08-e517acfde72e', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 2, 'Reduce heat to low, cover, and simmer until meat can be easily pulled from the bone, about 1 1/2 hours. Remove from heat and break meat up into smaller pieces using tongs, stirring it into the sauce. Let mixture cool to room temperature, at least 20 minutes.'),
('5a9df391-5b2d-4054-83ad-33d69c4bf305', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 3, 'Transfer meat to a mixing bowl, shredding it into smaller pieces. Discard bones, cartilage, and skin.'),
('ae1e7160-84a4-4c0b-8fbe-c44c686b2959', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 4, 'Bring the sauce in the pan to a boil over medium-high heat. Let reduce until slightly thickened, about 2 minutes. Pour sauce into the bowl of chicken meat and mix thoroughly. Taste for seasoning; add salt, cayenne, and hot sauce as needed. Add celery and mix one last time.'),
('73c93bd2-5f63-458b-85be-6cc2c1419a61', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 5, 'Pack chicken mixture into a pint-sized jar or crock, and top with a spoonful of hot sauce if desired, and seal jar. Refrigerate until ready to serve. Remove from fridge 30 minutes before service to allow spread to warm up a bit.'),
('097ef8f6-7e17-418d-8a7d-34b1153558cd', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 6, 'Preheat the oven to 350 degrees F (175 degrees C) in the meantime. Arrange baguette slices on a baking sheet. Brush tops generously with butter.'),
('92bd44ed-b78a-4d76-8f2a-f5e9de2ff453', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 7, 'Bake in the preheated oven until edges start to turn golden brown, about 20 minutes.'),
('e1c77e44-6a6f-48c7-8e88-323bcea2bb16', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 8, 'Meanwhile, smear butter and blue cheese together in a small bowl until combined.'),
('de51c2b2-1776-4483-8a9a-a8af307d6984', 'fcbe5f6e-1fe5-40d1-8adc-dde8fb077f0a', 9, 'Remove toasted baguette slices and let cool slightly, leaving the oven on. Spread blue cheese spread on top, then continue baking crostini until golden brown and crispy, 10 to 12 minutes. Serve with the Buffalo chicken spread.'),
('ecd8fd4b-7c64-4599-8e70-0e3a47413608', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 1, 'Preheat the oven to 425 degrees F (220 degrees C). Spray a rimmed baking sheet with cooking spray. Spread frozen tater tots in a single layer on prepared pan; drizzle lightly with about 1 tablespoon olive oil; season with about 1 tablespoon barbecue rub.'),
('b20db716-6a34-4de5-8eaf-4937e927b051', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 2, 'Bake in the preheated oven until golden brown and heated through, about 25 minutes, or according to package directions.'),
('89a4b34f-7aa4-41ba-8636-4040d41b37e4', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 3, 'Place chicken thighs and remaining 2 tablespoons olive oil in a large bowl. Season liberally with barbeque rub (about 1 tablespoon); toss to coat. Sear chicken in a non-stick skillet over high heat, turning occasionally, until deeply browned; reduce heat to medium.'),
('0a9da42c-6338-4f0c-8cda-382824efa409', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 4, 'Meanwhile, melt butter in a small saucepan over medium-low heat; stir in hot sauce, hot honey, and season to taste with barbecue rub; bring to a simmer.'),
('7cc21b4d-c58c-4bfb-853d-e674d3aab49c', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 5, 'Pour honey hot sauce over chicken in the skillet; increase heat to medium-high and cook chicken, basting constantly with the sauce, until chicken is fully cooked and coated with a shiny glaze, about 5 minutes. Chicken juices should run clear, and an instant-read thermometer inserted near the center should reach 165 degrees F (74 degrees C). Remove chicken to a cutting board; slice chicken into bite-sized pieces.'),
('5af261dc-a474-44b7-8b64-a57a09edec3b', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 6, 'Warm cheese sauce in the microwave on 50% power until hot, about 1 minute, stirring every 30 seconds.'),
('85df3e31-5088-447d-853e-e9e6dd5729cb', 'f26e0fdf-d47b-432e-8968-06e0f002aa31', 7, 'Arrange tater tots on a serving platter (or assemble on the sheet pan). Top tots with chicken and any remaining sauce from the pan; sprinkle with shredded cheese. Use a kitchen torch to melt cheese. Drizzle on additional hot sauce to taste and queso blanco; garnish with pickled red onion and parsley.'),
('1aa9d480-1c16-4b6f-87e0-bede937e14c5', 'dff0c484-1553-4f0a-8803-68da4c42d4f7', 1, 'Place the eggs into a saucepan in a single layer and fill with water to cover the eggs by 1 inch. Cover the saucepan and bring the water to a boil over high heat. Once the water is boiling, remove from the heat and let the eggs stand in the hot water for 15 minutes. Pour out the hot water, then cool the eggs under cold running water in the sink. Peel once cold.'),
('6dad0a96-be32-484c-80c7-40cb84ba48af', 'dff0c484-1553-4f0a-8803-68da4c42d4f7', 2, 'Preheat the oven''s broiler and set the oven rack about 6 inches from the heat source.'),
('af98091a-8faf-4e86-8610-b2016508a806', 'dff0c484-1553-4f0a-8803-68da4c42d4f7', 3, 'Coat beef and chicken livers with 2 tablespoons of corn oil, then spread livers on a baking sheet. Broil in the preheated oven until brown on the top, 8 to 10 minutes. Flip the livers and continue to broil until the livers are no longer pink in the center and juices run clear, about 5 minutes. Place livers in a bowl and chill in the refrigerator.'),
('eebe00e3-ceac-4f7e-8143-5ee263da6741', 'dff0c484-1553-4f0a-8803-68da4c42d4f7', 4, 'Heat 2 tablespoons of chicken fat and 2 tablespoons corn oil in a large skillet over medium-high heat. Stir in the onion; cook and stir until the onion has softened and turned translucent, about 10 minutes. Reduce heat to medium-low, and continue cooking and stirring until the onion is very tender and dark brown, 15 to 20 minutes more. Place onion in a bowl; cover and refrigerate until chilled.'),
('86845146-4ddf-4704-8c4d-30cc83247bf8', 'dff0c484-1553-4f0a-8803-68da4c42d4f7', 5, 'Finely chop the chilled beef and chicken livers, chilled onions, and hardboiled eggs together, then place in a bowl. Stir in the remaining 1 tablespoon of chicken fat. Season with salt and pepper. Refrigerate until ready to serve.'),
('71341bc7-1c8f-4180-8cae-3ca881e90535', '982abbc8-08d6-4c65-8738-df00d4b9fc13', 1, 'Place potatoes and salt in a medium saucepan and add water to cover by one inch. Place pot over high heat and bring to a boil. Cook until just tender, 8 to 10 minutes. Potatoes should not be soft. Drain and set aside until cool enough to handle.'),
('019d3936-6a79-4472-8a93-222da3c5b305', '982abbc8-08d6-4c65-8738-df00d4b9fc13', 2, 'Slice potatoes in half across the center and scoop out the center flesh carefully, leaving a 1/8 of an inch border of flesh. Combine sausage and queso in a medium bowl and stir until creamy.'),
('9f01e272-44d7-450d-8f93-bc3b50312b7b', '982abbc8-08d6-4c65-8738-df00d4b9fc13', 3, 'Place about 1 teaspoon chorizo mixture in one potato half and place 1 to 2 teaspoons of shredded cheese in the corresponding potato half. Press the two halves together allowing the starch from the potato to hold together as best as possible. Coat each potato in egg, allowing excess todrip, and lightly coat in breadcrumbs, taking care not to allow the potatohalves to separate.'),
('8c15cdc4-4acb-4f98-8d65-289d203ba883', '982abbc8-08d6-4c65-8738-df00d4b9fc13', 4, 'Preheat an airfryer to to 400 degrees F (200 degrees C). Spray potatoes lightly with oil or cooking spray.'),
('53099f3e-d4d1-47a7-8cb5-b2e4518bf803', '982abbc8-08d6-4c65-8738-df00d4b9fc13', 5, 'Air fry in batches if necessary until golden and crispy, 8 to 10 minutes. Let stand for 5 minutes before serving.'),
('f8502a1d-d36c-4de2-8826-73acb609d3da', 'dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 1, 'Place potatoes in a large pot and cover with water; bring to a boil. Reduce heat to medium-low and simmer until barely tender, about 8 minutes. Drain. Once cool enough to handle, peel and cut into cubes. Set aside.'),
('5ae108aa-2500-4349-8038-974057f183f6', 'dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 2, 'Meanwhile, melt butter in a large skillet and cook onion and green onions until softened, about 5 minutes. Add bell pepper and cook for 3 minutes. Add ground beef; cook and stir until beef is browned, about 5 minutes. Season with paprika, cayenne pepper, and salt.'),
('0831b158-4104-4744-8a51-15a4d5bf504a', 'dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 3, 'Remove beef mixture from heat; add potatoes and olives. Stir in chopped hard-cooked eggs; set filling aside to cool, about 20 minutes.'),
('b92fc59c-fb43-454b-8590-94df4fde2f20', 'dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 4, 'Preheat the oven to 425 degrees F (220 degrees C). Line 2 baking sheets with aluminum foil and lightly grease with olive oil.'),
('f4ad920f-070b-4656-87a0-95e475307d47', 'dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 5, 'Place an empanada pastry round on a flat surface and lightly wet the edges with warm water. Put a large tablespoon of cooled filling in the center and fold dough over. Seal edges by pressing with a fork. Repeat with remaining rounds and filling. Transfer empanadas to the prepared baking sheets and brush with beaten egg.'),
('a47fa6f3-57ac-48fd-8fc1-c963ac12e8e3', 'dc1e8b50-2f2a-4673-8ae2-cd0a1edf1726', 6, 'Bake in the preheated oven until golden brown, 15 to 20 minutes.'),
('c778600e-3377-439a-8ca2-ee9313de91c4', 'c84f6946-ce78-4367-89c8-0abc7603546f', 1, 'Preheat oven to 375 degrees F. Line a rimmed baking sheet with Reynolds Wrap® Aluminum Foil. Set aside. The sheet will catch any spills in the oven later on.'),
('fab502ba-c385-4bfd-8ee7-8986036220d4', 'c84f6946-ce78-4367-89c8-0abc7603546f', 2, 'Place the potato slices in a large pot and cover with cold water. Season with salt and bring to boil for 5 minutes. Drain in a colander and allow the potatoes to steam for 1 minute.'),
('fca4c287-60f1-4212-877d-62624e0c2752', 'c84f6946-ce78-4367-89c8-0abc7603546f', 3, 'Rub a 10-inch baking dish with the garlic clove and generously butter the dish. Finely chop the garlic. Set aside.'),
('758b0c37-19e7-4772-87d8-ec47d6f4f8d1', 'c84f6946-ce78-4367-89c8-0abc7603546f', 4, 'With the heat off, transfer the potatoes back to the pot and add heavy cream, thyme, half of the Parmesan cheese, chopped garlic, melted butter, salt and pepper. Stir all of the ingredients together until the potatoes are well coated.'),
('fd141168-d3bb-4f77-872e-2870d89cac1d', 'c84f6946-ce78-4367-89c8-0abc7603546f', 5, 'Layer the potatoes on top of each other in the buttered baking dish. Pour any remaining liquid on top of the potatoes. Place the baking dish on the prepared baking sheet. Cover the baking dish with foil and bake for 40 minutes. Remove the foil from the baking dish, add the remaining cheese and bake for 15-20 minutes, or until golden brown.'),
('c7a6cad2-f77a-4d67-82e9-e7992e5d00f3', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 1, 'Preheat the oven to 200 degrees F (95 degrees C). Line a rimmed baking sheet with paper towels, and set a wire rack inside.'),
('02100d14-f5dd-4f25-8fec-7a66ebb83ddf', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 2, 'Bring a large pot of lightly salted water to a rolling boil. Cook fettuccine at a boil until tender yet firm to the bite, about 8 minutes. Drain pasta in a colander over a heatproof bowl; reserve 1 1/2 cups pasta cooking water. Set fettuccine aside, and reserve pot.'),
('824a083b-d720-41e4-8984-e0b81dc8ff87', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 3, 'While pasta cooks, stir together breadcrumbs, flour, and 1/2 cup Asiago in a shallow dish until combined. Pour milk into a separate shallow dish. Season chicken on both sides with 1 teaspoon of the salt and 1/4 teaspoon of the pepper. Working with 1 cutlet at a time, dredge chicken in breadcrumb mixture. Dip in milk, and coat again in breadcrumb mixture, pressing firmly to adhere. Place prepared chicken on a plate.'),
('1da2b055-21c7-47d9-8397-10f4b04f61b6', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 4, 'Pour oil to a depth of 1/4-inch in a large skillet; heat oil over medium-high heat to 350 degrees F (175 degrees C). Place prepared chicken in hot oil, and pan-fry until golden brown and cooked through, 2 to 3 minutes per side. Transfer fried chicken to the prepared wire rack. Once all chicken is fried, remove paper towels.'),
('610aca2d-adaa-46a3-83ff-b0e3f7d66f0d', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 5, 'Place the baking sheet in the preheated oven to keep chicken warm until ready to serve.'),
('68e41ea1-3b0e-4f91-8e73-731ccbe2713e', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 6, 'Melt butter over medium heat in the reserved pasta pot. Add garlic, and cook, stirring constantly, until fragrant and butter is foamy, about 2 minutes. Stir in heavy cream, and cook until bubbling, about 2 minutes. Whisk in remaining 2 cups Asiago, stirring constantly until thickened, 1 to 2 minutes.'),
('f002ace6-71a7-453e-8ce2-b21425faf9dc', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 7, 'Add cooked pasta, and remaining 2 teaspoons salt and 1/4 teaspoon pepper; cook, stirring constantly, until pasta is coated in sauce, about 2 minutes, adding reserved cooking liquid as needed, 1/4 cup at a time, to thin the sauce.'),
('92bc53cd-a82a-4ee5-8ffe-fde50eb7f25b', 'e4c8851a-192a-40a8-800b-6a29cb1a36d4', 8, 'Slice chicken. Divide pasta among 4 large plates; top evenly with chicken, and garnish with parsley.'),
('1521e564-2705-4b0c-899d-26d4a0adda24', 'eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 1, 'Preheat the oven to 425 degrees F (220 degrees C). Line a baking sheet with a piece of aluminum foil and lightly grease.'),
('30c7ce3f-f333-4ec9-8226-149ab42cef25', 'eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 2, 'Peel turnips, and cut into French fry-sized sticks, about 1/3 inch by 4 inches. Place into a large bowl and toss with vegetable oil to coat.'),
('7122b7f9-293c-411f-8594-855deb9fee70', 'eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 3, 'Combine Parmesan, garlic salt, paprika, and onion powder in a resealable plastic bag; shake until well mixed.'),
('bea79a11-2fee-447d-8282-221722ba5fa5', 'eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 4, 'Place turnips into the bag and shake until evenly coated with the spices.'),
('67bc512b-b81d-4ba0-877d-cc6ca09b7c07', 'eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 5, 'Spread out onto the prepared baking sheet.'),
('d94da6f9-dae6-4355-899b-f2c4875194f8', 'eb923f8e-9d2a-4d6b-8fcc-d403308e5f66', 6, 'Bake in the preheated oven until the outside is crispy and the inside is tender, about 20 minutes. Serve immediately.'),
('3b14753f-69e0-41ea-8833-b61289736fd5', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 1, 'Preheat the oven to 350 degrees F (175 degrees C). Coat a 9x9-inch baking dish with cooking spray.'),
('74a39a0d-8e4f-4d48-89b5-ac4b76e03736', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 2, 'Pulse flour, brown sugar, butter, peach spice, and salt together in a food processor until the mixture resembles pea-sized crumbs. Press mixture into the bottom of the prepared baking dish.'),
('93693475-0090-4a99-8284-e682d06bf6cc', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 3, 'Bake crust in the preheated oven until golden and set, about 15 minutes.'),
('2b22563c-8b77-4f34-85d1-5f6efcc88828', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 4, 'While crust is baking, heat a saucepan over medium heat. Pour reserved peach juice into the saucepan; stir in sugar, cornstarch, and peach spice until smooth. Bring to a boil; cook and stir until thickened, about 2 minutes. Remove from heat; stir in canned and frozen peaches.'),
('acefa421-bfcf-4395-81cb-b50508f66c34', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 5, 'Remove crust from the oven and let cool for 5 minutes. Pour peach mixture into the crust.'),
('538f43d8-694d-4c54-811a-027b84cb50d3', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 6, 'Bake in the preheated oven until bubbling, about 20 minutes.'),
('c3da30c4-30d3-4257-8409-ed007c00a6e4', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 7, 'Meanwhile, combine cinnamon rolls together to form a square pastry disc. Roll out disc with a rolling pin on a lightly floured work surface. Cut into thin strips using a pizza cutter. Weave strips together to create a lattice topping.'),
('68651bd6-d850-4a19-82ba-7fab203d7998', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 8, 'Remove the baking dish from the oven; lay lattice over the peaches. Increase oven temperature to 375 degrees F (190 degrees C).'),
('625f6332-d22e-4939-89ac-2986f7414583', '8c0aa0da-1df6-4d1e-80c3-03d0cd1469ad', 9, 'Bake cobbler in the preheated oven until golden brown, about 12 minutes. Drizzle the included cinnamon roll icing over the lattice crust. Serve warm.'),
('c1023d2e-91d7-4dce-81fe-11ba5b450cc3', '0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 1, 'Coat a 9x13-inch metal baking pan with cooking spray and 1 tablespoon olive oil and place inside the oven. Preheat the oven to 375 degrees F (190 degrees C). C'),
('29468fa1-2f45-4b27-87b6-7d41c4d98b26', '0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 2, 'Combine chickpeas, onion, cilantro, parsley, garlic, lemon zest, cumin, salt, red pepper flakes, and baking powder in a food processor. Pulse until minced but not yet pasty. Transfer to a bowl and stir in flour and egg until fully incorporated.'),
('f195426f-0690-493c-80a5-8185891246f9', '0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 3, 'Remove baking pan from the oven. Drop golfball-sized portions of chickpea mixture onto the hot pan.'),
('c90e5cc3-fd9b-4675-887b-f40b7a0cf6e0', '0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 4, 'Bake in the preheated oven 15 to 20 minutes. Brush falafel with remaining olive oil and flip over. Continue baking until golden on both sides, 15 to 20 minutes more.'),
('82c05ee8-c1e4-4ec1-82af-0ccf33351573', '0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 5, 'Meanwhile, combine yogurt, cucumber, lemon juice, and garlic in a bowl. Season with salt and cayenne pepper. Store in the refrigerator until ready to serve.'),
('6f06ff74-098d-4b7d-8da5-785d6b262be7', '0e21946b-4e5b-4bb5-88ae-17cad7f1c7ce', 6, 'Serve falafel with yogurt sauce.'),
('f7f0ef68-d7df-4fba-8daf-62589faac4db', '30437522-da47-49c9-8b17-065100b09ff8', 1, 'Gather the ingredients.'),
('95bd30ce-4d01-4abf-8387-9b0ee89c991d', '30437522-da47-49c9-8b17-065100b09ff8', 2, 'Dip eggplant slices in egg, then coat with bread crumbs. Heat olive oil in a large skillet over medium-high heat.'),
('a0d752aa-a8da-40cd-8ae8-82714799fca6', '30437522-da47-49c9-8b17-065100b09ff8', 3, 'Fry eggplant slices on each side until golden brown. Remove to a paper towel lined plate to drain. Preheat the oven to 350 degrees F (175 degrees C).'),
('7c834327-8258-4aad-8f44-f1a912ccda89', '30437522-da47-49c9-8b17-065100b09ff8', 4, 'Spread a thin layer of ricotta cheese onto each slice of eggplant. Place a slice of prosciutto onto each one. Roll up tightly, and place seam-side down in a 9x13-inch baking dish. Pour tomato pasta sauce over eggplant rolls, and top with shredded mozzarella cheese.'),
('d81ff1ae-9a1a-43e0-8241-b669e83dd4db', '30437522-da47-49c9-8b17-065100b09ff8', 5, 'Bake for 15 minutes in the preheated oven, until the cheese is melted and lightly browned.'),
('22926996-eff3-4d2a-82b0-1f2a9da169d8', '30437522-da47-49c9-8b17-065100b09ff8', 6, 'If you want to serve the eggplant rollatini on pasta, bring a large pot of lightly salted water to a boil while eggplant rolls are baking. Add pasta, and cook for 2 to 3 minutes, until tender. Drain.'),
('137e8ba5-f32c-40ad-87bc-a04a2f22a7b5', '30437522-da47-49c9-8b17-065100b09ff8', 7, 'Serve eggplant rolls and sauce over pasta.'),
('73edfdff-8dfe-4e4e-87aa-df26ae4d2581', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 1, 'Preheat the oven to 400 degrees F (200 degrees C). Prick each potato a few times with a fork and place on a baking sheet.'),
('4c5b195b-4adf-43d4-8d1d-c63dad411a68', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 2, 'Bake potatoes in the preheated oven until tender when pierced with a knife, about 50 minutes. Cool until easily handled, about 10 minutes.'),
('8fb69786-88f1-46aa-8637-0ff8bbb21598', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 3, 'Peel potatoes and pass through a ricer or food mill into a large bowl. Make a well in the center and pour in egg; mix well.'),
('b163b679-9786-4212-8380-712cd4b6dbb4', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 4, 'Whisk potato starch, sweet rice flour, and salt together in a bowl. Sprinkle over potato mixture; stir until a soft dough has formed. Cut dough into 4 equal parts with a knife or pastry cutter.'),
('9926ceab-5b1b-438e-8833-d148223471d4', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 5, 'Dust the work surface with rice flour to keep dough from sticking. Roll out 1 piece of dough into a rope about 1 inch in diameter. Cut into 1-inch gnocchi. Gently roll each one with the back of a fork to create ridges. Repeat with remaining dough.'),
('ad9b81f6-a790-4e35-8fc2-c2ed828ba0ec', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 6, 'Shake off any excess rice flour and let gnocchi rest, about 5 minutes.'),
('9555b8c0-bdf9-4769-8a89-a2cb4cc3ae2d', '3d5e8391-0b20-4f86-8de8-2f47b0f17658', 7, 'Bring a large pot of salted water to a boil. Add gnocchi in batches and cook, without stirring, until they float to the top, 1 to 2 minutes. Remove with a slotted spoon.'),
('b29addec-dd23-4050-84b4-be067a48d5ec', '00f3ed38-4474-4722-8d75-845db3662157', 1, 'Preheat the oven to 350 degrees F (175 degrees C). Lightly spray an 8x8-inch baking dish.'),
('7138a192-de7f-476b-8a48-1b1c570947b7', '00f3ed38-4474-4722-8d75-845db3662157', 2, 'Place bacon in a large skillet and cook over medium-high heat, turning occasionally, until evenly browned, about 10 minutes. Drain bacon slices on paper towels. Crumble once cooled.'),
('95633afe-f124-442f-8adf-fb78a265eb6e', '00f3ed38-4474-4722-8d75-845db3662157', 3, 'Saute onion in the same skillet until translucent, 4 to 5 minutes. Add green chiles and garlic and cook for 2 more minutes. Add pinto beans; bring to a boil. Stir in chicken broth and chili powder. Reduce heat to low and mash beans. Let simmer until slightly thickened, 5 to 6 minutes. Add cream cheese and stir until melted. Simmer until slightly thickened, 5 to 6 minutes. Add bacon and stir until well combined. Season with salt and pepper.'),
('b5134cb8-58bd-48cf-879a-6228932d7858', '00f3ed38-4474-4722-8d75-845db3662157', 4, 'Layer 1/2 of the bean mixture, 1/2 cup pepper Jack, and 1/2 cup Cheddar cheese into the prepared baking dish. Repeat layers.'),
('3500bfcc-26eb-49ef-8a57-d75b2fee2526', '00f3ed38-4474-4722-8d75-845db3662157', 5, 'Bake, covered, in the preheated oven for 15 minutes. Uncover and continue baking until cheese is melted or lightly browned, 5 to 7 minutes more.'),
('41ad5654-0002-4482-87ac-113028dfe212', '00f3ed38-4474-4722-8d75-845db3662157', 6, 'Meanwhile, preheat an air fryer to 350 degrees F (175 degrees C) according to manufacturer''s instructions.'),
('4e906085-6ce1-421f-8e47-a41cb590d865', '00f3ed38-4474-4722-8d75-845db3662157', 7, 'Cut each tortilla into fourths. Spray both sides of each tortilla with avocado oil. Place in air fryer basket in a single layer. Air fry for 4 to 6 minutes. Flip and continue cooking until crisp, 2 to 3 minutes more. Check your basket constantly because they can burn quickly. Sprinkle with salt and serve with hot dip.'),
('7e19c708-85e4-4d47-84cd-776c36a70daa', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 1, 'Place potatoes into a large pot and cover with salted water; bring to a boil. Reduce heat to medium-low and simmer until tender, about 20 minutes. Drain.'),
('67f6b576-2f76-4d77-89a5-8aa254ea383d', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 2, 'Combine flour, buttermilk, water, and 1 teaspoon salt in a bowl. Whisk with a fork; when the dough thickens, start kneading by hand. Knead for at least 10 minutes, applying all of your strength so you will have to put less effort into rolling. Cover dough and let rest at least 30 minutes.'),
('e98f6dff-7767-4205-8d7c-69b4bf0a2011', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 3, 'Peel and mash the boiled potatoes in a bowl. Add mozzarella cheese and combine well. Add salt to taste if the mixture is too bland. Divide filling into 12 balls; place on a plate or baking sheet and cover.'),
('96f93885-c4df-46fd-8c64-c06e0dccc710', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 4, 'Divide dough into 12 balls; these will be smaller than the filling balls. Place on a plate or baking sheet and cover.'),
('5ade0687-7d55-4c17-8d93-16639134f730', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 5, 'Stretch 1 piece of dough into a small, flat circle. Place a filling ball in the center; pull up the edges of the dough and secure to have a ball encased in dough. Repeat with remaining dough and filling.'),
('8484ea53-dd54-4336-8c61-4125d2e38fa7', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 6, 'Heat a heavy-bottomed frying pan over medium heat; use no oil or grease. Place melted butter in a bowl nearby. Sprinkle a work surface with a generous amount of flour. Carefully and gently start to roll out a ball; the dough will be hard to work at first. Be careful not to press too hard with the rolling pin to avoid rips; roll into a circle about 1/4-inch thick.'),
('6a2ba7b8-06ee-4e7e-8e4b-0facd947c115', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 7, 'Place hychin into the hot pan. Fry until golden-brown spots appear, about 2 minutes. Pierce with a knife to deflate, if necessary. Turn over and cook on the other side, about 2 minutes more. Brush generously with butter and transfer to a plate. Repeat with remaining balls and stack cooked hychin on the plate.'),
('76d951af-5e57-4e10-89e2-7abecd8597a6', '608cb44b-38f7-4008-8a1e-ea0bc7bf916b', 8, 'Cut the whole hychin stack into 8 slices like a pie.'),
('7f07bec1-5305-448a-80b0-1d83080aa777', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 1, 'Gather all ingredients.'),
('15e9d5e6-6fb8-4257-894d-e5091107df6c', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 2, 'Bring a large pot of salted water to a boil; add lasagna noodles and cook for 4 to 5 minutes. Drain, toss in 1 tablespoon olive oil in the lasagna pot or in a large bowl, and set aside.'),
('b9b4f071-26e5-4d49-8fe4-e317fdffee81', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 3, 'Add a drizzle of olive oil to a large skillet; place over medium heat and sauté garlic until fragrant, about 30 seconds. Add 2 cups spinach and cook until just wilted, about 3 minutes. Remove from the pan and use kitchen shears to roughly chop the spinach; add to a small bowl and stir in ricotta and 1/4 cup Parmesan. Season with salt and pepper. Set aside.'),
('1d712cc9-0ee2-4add-8dc3-ca06ecfe68d7', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 4, 'Cook sausage in the same skillet over medium heat until browned and cooked through, breaking it into crumbles, about 5 minutes. Add artichokes and sauté for 2 to 3 minutes. Pour in cream and bring to a gentle simmer. Season with salt, pepper, and red pepper flakes. Simmer until slightly thickened, 2 to 3 minutes, then stir in remaining spinach and cook until just wilted.'),
('a88b98a9-7cef-4303-8d77-2bf257ac44c1', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 5, 'Pour sausage mixture into lasagna noodles. Stir in 1/2 cup Parmesan and half of mozzarella. Mix until cheese is melted and lasagna noodles are fully coated.'),
('2e9ba74b-ae85-4aac-8e0e-2ce5109758dd', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 6, 'Preheat the oven to 425 degrees F (220 degrees C). Lightly grease a 18x13-inch baking sheet or 9x13-inch baking dish.'),
('977f7036-5dd4-4956-8da6-5191716a2928', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 7, 'Spread pasta mixture evenly across the prepared pan. Dollop ricotta-spinach mixture over the top. Sprinkle mozzarella cheese and Parmesan evenly across the entire surface.'),
('87efceed-a8fa-451a-83a2-6aff80638b3a', '98da70d7-b8a7-42b5-88ab-c8c000c0796b', 8, 'Bake in the preheated oven until bubbling and golden, 15 to 20 minutes. Optionally, for a more golden crust, turn on the oven''s broiler and broil the top for 1 to 2 minutes at the end. Let cool slightly, garnish with fresh herbs if desired, and cut into squares to serve.'),
('5f285f30-aa9c-47b4-8f97-8fa11182374e', '3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 1, 'Place eggs in a saucepan; cover with water. Bring to a boil, remove from heat, and let eggs stand in water for 15 minutes. Remove eggs from water, cool under cold running water, and peel.'),
('62ea292a-4b9d-40ae-8189-f4f88e35f546', '3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 2, 'Place bacon in a large skillet; cook over medium-high heat, turning occasionally, until evenly browned, about 10 minutes. Drain on paper towels; crumble when cool.'),
('b524bfdb-3b89-4114-8e1e-b94139c18fd0', '3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 3, 'Remove seeds and stems from jalapeños; mince 1 pepper and slice remaining 2 peppers into 24 very thin strips; set aside.'),
('4b1bb2f6-b631-46ed-87c4-4690946af8fa', '3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 4, 'Cut eggs in half lengthwise; place yolks in a bowl. Mash with a fork; stir in minced jalapeño, Cheddar cheese, mayonnaise, red onion, and mustard.'),
('fb053af2-b629-498b-85f0-9cf15db65af0', '3d8e8d5f-abc8-43ba-8379-65fa56f66d7b', 5, 'Place egg whites, cut side up, on a serving platter. Spoon yolk mixture into egg white halves; insert pepper strip into each yolk; sprinkle with crumbled bacon and paprika.'),
('81661a55-e5ee-492b-82f3-b9657f8ab1ff', '9ad6f83e-c441-4a91-84ce-3c3475373cf0', 1, 'Bring a large pot of water to a boil. Cut the ends off of the bananas, and make a slit lengthwise down the peel. Cook bananas in boiling water until tender (similar to a potato). Drain, cool, and remove peels. Cut into small chunks and place in a serving bowl. Drizzle 1 tablespoon of olive oil over the pieces, and stir to coat.'),
('a27dc69d-35c7-433b-8018-ae6b9bbb7a39', '9ad6f83e-c441-4a91-84ce-3c3475373cf0', 2, 'Meanwhile, heat the remaining tablespoon of oil in a skillet over medium-high heat. Add shrimp and crab, and fry until cooked through, about 5 minutes. Set aside to cool.'),
('5caf51ad-8cfb-4d6a-8731-594e3e697777', '9ad6f83e-c441-4a91-84ce-3c3475373cf0', 3, 'Add onions, green pepper and seafood to the bananas in the bowl. In a separate bowl, whisk together the red wine vinegar, sugar and bacon pieces. Pour this mixture over the bananas, and toss lightly to coat. Season with salt and pepper. Garnish with slices of hard-cooked egg if desired.'),
('a7446a71-7702-4d91-81f2-e802ea96b06f', 'a7da003c-4ec6-433a-817a-2007ed13e26b', 1, 'Preheat the oven to 200 degrees F (95 degrees C). Place a serving platter into the oven to warm.'),
('fbbe4378-1215-4902-8891-bdcfa3fc9075', 'a7da003c-4ec6-433a-817a-2007ed13e26b', 2, 'Season chicken breast pieces with salt and pepper and dredge them in flour. Shake off excess flour. Heat vegetable oil in a skillet; pan-fry the chicken pieces until golden brown on both sides, about 3 minutes per side. Work in batches and do not crowd skillet, adding oil as needed. Place chicken pieces onto the warmed platter in the oven. When finished with all of the chicken, drain most of the oil from the skillet, leaving a thin coating on the surface of the pan.'),
('e57a382c-eb05-441c-86ba-8ed5a7ddb741', 'a7da003c-4ec6-433a-817a-2007ed13e26b', 3, 'Cook and stir minced garlic in the skillet until fragrant, about 20 seconds. Pour in chicken broth; scrape and stir any brown bits from the bottom of the skillet. Stir in lemon slices and bring the mixture to a boil. Let cook, stirring occasionally, until the sauce reduces to about 2/3 cup, 5 to 8 minutes. Add lemon juice and capers; simmer until sauce is reduced and slightly thickened, about 5 minutes more. Drop butter into the skillet and swirl it into sauce by tilting the skillet until butter is melted and incorporated. Add parsley; remove from heat and set aside.'),
('ecd92208-7325-4b6c-816b-ee4b5fb05dc6', 'a7da003c-4ec6-433a-817a-2007ed13e26b', 4, 'Arrange chicken medallions on serving plates and spoon sauce over each portion to serve.'),
('e8d58d6b-be70-4fbc-8146-0eccf44ce18d', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 1, 'Preheat the oven to 450 degrees F (230 degrees C). Butter a 13x9-inch baking dish.'),
('eb225511-4037-4c7d-8e77-596cf0a1b8b0', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 2, 'For the mashed potato, add quartered russet potatoes to a pot with 3 tablespoons salt and enough water to cover by 2 inches. Bring to a boil over high heat; reduce heat to medium and simmer until tender when pierced with a sharp knife, but not falling apart, 15 to 20 minutes. Drain very well.'),
('bf53b516-a409-4b9d-8d17-fb04a0d6d200', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 3, 'Return potatoes to the pot, and mash until almost smooth. Add butter, salt, and cayenne. Mash until smooth.'),
('98503abd-b21a-4501-874b-bf7c79377a1b', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 4, 'Add milk and the 4 ounces shredded cheese, and mash and mix until evenly combined. Spread evenly into the prepared baking dish, and smooth the top. Season the top with salt and freshly ground black pepper.'),
('5c96838f-4576-4b0f-8108-810c11d9e038', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 5, 'For the au gratin potato layer, slice each half potato into 1/8-inch slices.'),
('b1f7c29e-f386-4682-8035-0ee8f48f55ce', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 6, 'Fan the potato out slightly at an angle, and place on top of mashed potatoes. Repeat with remaining potato halves to cover the surface, creating 4 rows across by 2 potato halves long, using 8 halves total. Depending on the size of potato and dish, you may have to adjust the layout to cover.'),
('0ca09938-56e0-4b68-877b-f84c0aa5112b', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 7, 'Generously salt sliced potatoes, and brush generously with melted butter. Scatter the 2 ounces shredded cheese on top, and finish with grated Parmigiano-Reggiano.'),
('8f0a557d-0306-4000-8f5f-93102b38e9f8', '68e28acb-f4ca-4715-8bc4-bd21cc85d96d', 8, 'Bake in the preheated oven until sliced potatoes on top are tender when pierced with a knife, about 1 hour.'),
('694288bf-1297-4758-851b-36fcbb43c4eb', 'ee4c8735-2376-41a2-816a-d0184aaf437d', 1, 'Place the potatoes into a large pot and cover with salted water. Bring to a boil; reduce heat to medium-low, cover, and simmer until tender, about 20 minutes. Drain. Cover with cold water and allow to sit until cool, draining and replacing the cold water as needed. Peel and slice the potatoes thinly.'),
('2d112a8d-f85d-4d7e-8d94-aa3f102ac8aa', 'ee4c8735-2376-41a2-816a-d0184aaf437d', 2, 'Preheat an oven to 350 degrees F (175 degrees C).'),
('e4f8bd0a-5b0c-47cb-8116-394ff5ffc332', 'ee4c8735-2376-41a2-816a-d0184aaf437d', 3, 'Grease a casserole dish with the olive oil. Line the casserole dish with an even layer of potato slices; top with a layer of sardine fillets. Scatter the diced tomatoes over the sardines. Sprinkle the garlic, basil, and bread crumbs over the tomatoes.'),
('20d61e89-e002-4c0a-8a59-bd1c5f4d708a', 'ee4c8735-2376-41a2-816a-d0184aaf437d', 4, 'Bake in the preheated oven until heated through, about 20 minutes.'),
('769d6654-5997-4111-8448-ff9c64ae9db5', '80640f12-2148-4b50-8637-f83a257d54e5', 1, 'Pour 2 cups oil (or amount needed for a depth of 1 inch) into a deep skillet; heat over medium heat.'),
('79b6f5bc-5fc0-48f2-8113-d8a2fe9d59b2', '80640f12-2148-4b50-8637-f83a257d54e5', 2, 'Pat eggplant slices dry with a paper towel. Set aside 4 whole basil leaves; chop remaining leaves.'),
('f515596c-824c-48ac-8490-6c57ec864b7c', '80640f12-2148-4b50-8637-f83a257d54e5', 3, 'Fry eggplant in batches in hot oil until golden, 2 to 3 minutes per side. Transfer eggplant to a paper towel-lined plate using a slotted spoon; season with salt.'),
('800a250f-6b07-4e5f-8a4b-c176379a5394', '80640f12-2148-4b50-8637-f83a257d54e5', 4, 'Simmer passata, 1 tablespoon olive oil, garlic cloves, 4 basil leaves, and a pinch salt in a saucepan over medium heat for 10 minutes. Remove from the heat and discard garlic cloves.'),
('92ddcdd2-7c55-48f6-8961-6381574baaa2', '80640f12-2148-4b50-8637-f83a257d54e5', 5, 'Preheat the oven to 375 degrees F (190 degrees C). Lightly grease a baking dish.'),
('51b71c39-42c5-4e00-8bc0-9bf6b0fd6746', '80640f12-2148-4b50-8637-f83a257d54e5', 6, 'Layer ingredients in the baking dish in the following order as many times as possible: fried eggplant, tomato sauce, mozzarella cheese, oregano, Parmesan cheese, and basil leaves. End with a layer of mozzarella and a drizzle of remaining 1 tablespoon olive oil.'),
('97d6e5e8-98c0-4fec-899e-51506c8081b6', '80640f12-2148-4b50-8637-f83a257d54e5', 7, 'Bake in the preheated oven until heated through and cheeses are melted, about 40 minutes. Let stand a few minutes before slicing.'),
('d237374c-4eb1-4150-8d77-be30b3df1637', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 1, 'Preheat the oven to 400 degrees F (200 degrees C). Line baking sheets with aluminum foil.'),
('f8504b4c-a67c-4786-88df-809f8327c602', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 2, 'Make sauce: Melt butter in a skillet over medium-high heat. Whisk flour into hot butter and cook, whisking constantly, until mixture is pale and flour taste cooks off, about 1 minute. Whisk milk into flour mixture until mixture is hot and thickened, 3 to 6 minutes. Add provolone cheese, nutmeg, cayenne pepper, and salt; stir until cheese is completely melted. Set aside.'),
('da30fc70-abfb-45e5-8bac-5590b4f9aeb7', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 3, 'Make mini cheesesteaks: Season steak with salt and black pepper.'),
('55e5a5e5-a87e-4f6e-82f9-75315b71deaa', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 4, 'Heat 1 tablespoon olive oil in a skillet over medium-high heat. Cook steak in hot oil, turning occasionally, until meat is slightly firm and pink on the inside, 5 to 7 minutes. Transfer meat to a plate.'),
('c65bae6a-2868-45de-8e1a-096c684caa43', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 5, 'Return the skillet to heat and pour in water; bring to a boil while scraping the browned bits of food off of the bottom of the pan with a wooden spoon. Pour liquid from the skillet over steak. Cool steak to room temperature; dice meat and place meat and accumulated juices from the plate into a large bowl.'),
('45251f27-2d32-4c43-8989-895be4c0b3cb', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 6, 'Heat 1 tablespoon oil in a skillet over medium-high heat; sauté onion and peppers in hot oil until softened and slightly translucent, about 5 minutes. Stir onion and peppers into beef in the bowl; season with salt and pepper.'),
('2640e609-49b8-4b1f-8664-bd540c505627', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 7, 'Spread bread slices out on the prepared baking sheets and drizzle with remaining 1 tablespoon olive oil. Flip slices over so the oiled sides face downward. Spread cheese sauce generously onto each slice. Spoon beef mixture on top. Sprinkle with provolone cheese.'),
('76c4d53d-c450-4358-8a0d-ec1fba0f550c', '228d7559-917a-4bc5-8bd9-bc3a9ffcaa60', 8, 'Bake in the preheated oven until browned and cheese is melted, 12 to 15 minutes.'),
('a995133e-fe04-42e3-855a-c276dfef102d', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 1, 'Heat oil in a large pot over medium heat. Add onion; saute until translucent, about 5 minutes. Mix in tomato puree and water; cook for 10 minutes. Stir in sugar and basil. Reduce heat to low; simmer for 30 minutes, stirring occasionally.'),
('5e3b0a0a-3da9-4147-807a-93801dbf609e', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 2, 'While the sauce is cooking, bring a very large pot of lightly salted water to a boil. Add ziti and cook, stirring occasionally, until tender yet firm to the bite, about 8 minutes. Drain and return to the pot.'),
('fa292f16-ada9-4102-871e-8b2ddc3f02f8', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 3, 'Heat a large skillet over medium-high heat. Cook and stir ground beef in the hot skillet until browned and crumbly, 5 to 7 minutes. Drain and discard grease. Add ground beef to cooked pasta. Mix in enough tomato sauce to lightly coat the pasta.'),
('feb8af44-d275-4590-8940-c48d5b81bf89', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 4, 'Mix ricotta cheese and water in a bowl until it reaches a spreadable consistency.'),
('e8696c71-32ee-471f-8eef-940fb0b5e977', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 5, 'Preheat the oven to 375 degrees F (190 degrees C).'),
('d756ed4c-43be-4532-8a1b-e192e4e4260d', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 6, 'Spread a ladleful of sauce in the bottom of a 9x13-inch baking dish. Add 1/2 of the pasta, all of the ricotta cheese, peas, and 1/2 of the Parmesan cheese. Layer the sliced eggs on every section of the pasta; cover with 1/2 of the mozzarella cheese. Pour remaining pasta, Parmesan cheese, sauce, and mozzarella on top. Cover with aluminum foil.'),
('af231184-0483-43b5-832c-875f3ce30134', 'bc9bc0fc-63fa-4543-864d-fe7e04fa365a', 7, 'Bake in the preheated oven until golden brown and bubbly, 40 to 50 minutes. Let stand for about 10 minutes before cutting, so slices don''t fall apart.'),
('e13f8006-91f8-43cf-8f3c-6c0296e2a1b0', 'f508be48-aec6-4c02-8822-0c15317b1e92', 1, 'Preheat the oven to 350 degrees F (180 degrees C). Lightly oil a loaf pan.'),
('6240f8f2-8afc-4b4d-8354-46204d55b7a8', 'f508be48-aec6-4c02-8822-0c15317b1e92', 2, 'Heat 1 tablespoon vegetable oil in a nonstick skillet over medium-high heat and sauté yellow onions with a pinch of salt until they start to turn golden, 3 to 5 minutes. Stir in 3 cloves crushed garlic and 2 teaspoons ginger, and cook for 1 minute more. Remove from heat and let cool to room temperature, about 15 minutes.'),
('4cfff9ae-6928-4e81-8e7c-f0465dd2cde6', 'f508be48-aec6-4c02-8822-0c15317b1e92', 3, 'Add cooled onion mixture to ground beef along with rice, egg, green onions, 1 tablespoon soy sauce, salt, and black pepper. Use a fork, spatula, or your hands to mix together until evenly combined. Transfer to the prepared loaf pan, press in firmly, and smooth the top.'),
('141bad4b-836b-4939-8b92-a99f689f8545', 'f508be48-aec6-4c02-8822-0c15317b1e92', 4, 'Bake in the preheated oven until an instant read thermometer inserted in the center reads 145 to 150 degrees F (63 to 65 degrees C), about 1 hour. Meatloaf can be served hot, or let cool, wrap and refrigerate until chilled, about 45 minutes.'),
('cbfb2ceb-1ecb-437e-832a-a84c82b0a986', 'f508be48-aec6-4c02-8822-0c15317b1e92', 5, 'For the sauce, combine 2 teaspoons oil, 1 tablespoon ginger, and 4 minced garlic cloves in a cold nonstick skillet.'),
('d108b6ed-b821-48b3-8410-0de4c05db4b9', 'f508be48-aec6-4c02-8822-0c15317b1e92', 6, 'Turn heat on to medium-high. Once ginger and garlic start to sizzle, cook, stirring, for about 30 seconds, then whisk in brown sugar, 1/2 cup soy sauce, 1/4 cup water, ketchup, and red pepper flakes. Bring to a simmer, then reduce heat to low.'),
('51b7b24c-eefe-4f68-8646-a2fbaf547087', 'f508be48-aec6-4c02-8822-0c15317b1e92', 7, 'Whisk 1 teaspoon cornstarch with 2 teaspoons water together in a small bowl to make a slurry; stir into the sauce. Raise heat to medium-high and return to a simmer. Cook, whisking occasionally, until sauce thickens slightly, about 2 minutes. Reduce heat to low and keep warm until needed (Sauce may be made ahead and reheated on medium-low heat).'),
('80cb89b8-b920-44b2-874a-8946e2252eb5', 'f508be48-aec6-4c02-8822-0c15317b1e92', 8, 'Remove cold meatloaf from the refrigerator and slice into 8 portions. Dust each side with cornstarch, and reheat over medium high heat in a nonstick skillet in a little bit of vegetable oil until browned and heated through. If surface browns before meatloaf is heated through, reduce heat to medium, and cover until done.'),
('2d80dbf1-c236-42c5-85e7-bb5eb4fd82e6', 'f508be48-aec6-4c02-8822-0c15317b1e92', 9, 'Serve topped with the sauce; garnish with toasted sesame seeds, sliced green onions, and chopped cilantro if desired.'),
('7137fe37-29e3-40e2-8d64-f8dc01c80154', '88b607bd-639d-4c73-82af-f4283c8e74e1', 1, 'Preheat the oven to 325 degrees F (165 degrees C).'),
('026ddf9f-5a16-4e67-826f-38aa7ef1cc9e', '88b607bd-639d-4c73-82af-f4283c8e74e1', 2, 'Make the pork: Remove the netting or strings from pork roast, keeping them intact to use again. Combine rosemary, parsley, garlic, 3 teaspoons oil, 1 tablespoon kosher salt, and 1 tablespoon pepper in a bowl. Slice open pork roast and spread it with herb mixture. Roll up pork and secure it with the netting or string. Rub remaining 1 teaspoon oil all over pork; season with more salt and pepper.'),
('553b22e9-2f0f-46c2-8853-1e496f4f6d14', '88b607bd-639d-4c73-82af-f4283c8e74e1', 3, 'Place pork, fat-side up, in a roasting pan; pour in water.'),
('8737326d-7b6f-4b9d-8d8d-2c89fa7f6d05', '88b607bd-639d-4c73-82af-f4283c8e74e1', 4, 'Bake in the preheated oven, basting occasionally and adding more water if necessary, until an instant-read thermometer inserted into the meat reads at least 145 degrees F (63 degrees C), 1 1/2 to 2 hours. Remove from the oven and let rest for 10 to 15 minutes. Reserve pan juices in the roasting pan.'),
('a3b62f32-0005-4da3-8ac2-bd9f50508bfc', '88b607bd-639d-4c73-82af-f4283c8e74e1', 5, 'While the pork is resting, prepare fixings: Heat oil in a frying pan over medium heat. Stir in garlic and red pepper flakes; cook and stir until garlic is fragrant but not brown, about 3 minutes. Pour in chicken stock and bring to a boil. Add spinach, lemon juice, salt, and pepper. Reduce the heat to medium-low and cook, stirring occasionally, until spinach is wilted, 2 to 3 minutes.'),
('db66df08-1482-4a10-8a96-068df1801a31', '88b607bd-639d-4c73-82af-f4283c8e74e1', 6, 'Cut and remove the string from the roast. Cut pork into thin slices. Return sliced pork to the juices in the roasting pan.'),
('b307a53a-584d-488b-8d27-25313600cf17', '88b607bd-639d-4c73-82af-f4283c8e74e1', 7, 'Slice sandwich rolls. Sprinkle Manchego cheese over split rolls, add pork slices, and top with spinach.'),
('b9732f96-6929-43ea-893f-b6142b5dfd17', 'c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 1, 'Preheat the oven to 400 degrees F (200 degrees C). Butter an 8x8-inch baking dish.'),
('ab83948b-a04a-4046-80ac-da22c93c1b61', 'c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 2, 'Fit a food processor with a shredding disk and use it to shred cheese. Transfer to a small bowl. Fit processor with slicing disk and use it to slice potatoes.'),
('69dde5ce-37d9-468b-8072-bfd5d55b78be', 'c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 3, 'Put potatoes in a large saucepan with half-and-half, garlic, salt, and nutmeg; stir gently to combine. Bring to a boil over medium-high heat, stirring occasionally. Cook at a gentle boil, stirring often with a heat-safe spatula to prevent sticking, until half-and-half has reduced and thickly coats potatoes, about 8 minutes.'),
('7dbed613-8f4f-426b-87a8-b8a84f6a3e15', 'c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 4, 'Spoon into prepared baking dish. Smooth top and sprinkle evenly with cheese.'),
('814674d3-7787-4c92-852e-d8e779774f29', 'c7d8a4b1-54c4-4135-8fc9-54a5dbc758c9', 5, 'Bake in preheated oven until potatoes are tender when pierced with a knife and top is golden brown, 25 to 30 minutes. Let stand 5 to 10 minutes before serving.'),
('d0fbbd14-ca65-4431-8106-6bcfcb49e2d2', '95953cbf-395b-485f-8506-375c0ae0510d', 1, 'First make the syrup: Add white sugar, water, cinnamon stick, and citrus peel to a medium saucepan. Place over medium heat and bring to a boil. Once boiling, boil for 2 minutes and remove from heat. Let cool completely. (This can be done up to a week in advance; store the cooled syrup in the refrigerator until needed.)'),
('0fe5e991-3dff-4e5f-8f1c-8e4bbe03beeb', '95953cbf-395b-485f-8506-375c0ae0510d', 2, 'Preheat the oven to 350 degrees F (180 degrees C). Brush a 9x13-inch baking dish with some of the melted butter.'),
('58a43738-3a1e-4d81-8b7e-37c0a23d7e9f', '95953cbf-395b-485f-8506-375c0ae0510d', 3, 'Place walnut halves in a food processor and pulse several times until they resemble fine crumbs. Combine walnuts with shredded pumpkin, breadcrumbs, olive oil, sugar, cinnamon, and ground cloves. Stir until well combined.'),
('51f0e247-9d6c-4c2f-8437-d770ae57dd71', '95953cbf-395b-485f-8506-375c0ae0510d', 4, 'Unroll phyllo dough and remove one sheet from the stack. Cover remaining phyllo with a dampened tea towel to keep from drying out as you work. Brush the sheet of dough with melted butter and lay in the prepared baking dish; press lightly so the sheet covers the bottom of the dish and comes up the sides. Repeat until you have 8 sheets layered. Do not worry if there are some tears in any of the sheets, this is expected and won''t affect the final result!'),
('6b6a650f-9d72-4b41-8aa0-e60828a62304', '95953cbf-395b-485f-8506-375c0ae0510d', 5, 'Spoon the pumpkin mixture over the phyllo base and level out to the sides. Fold the overhanging phyllo over the top of the pumpkin mixture.'),
('7f90c827-f05d-4aaf-8a91-ff62ba3e7706', '95953cbf-395b-485f-8506-375c0ae0510d', 6, 'Brush another sheet of phyllo dough with melted butter and lay over the pumpkin mixture. Repeat until you''ve topped with 6 to 8 sheets. Use your pastry brush to scrunch the overhanging phyllo down into the sides of the baking dish. Drizzle any remaining melted butter all over the top of the baklava.'),
('2baf2541-1327-4ae2-8116-0fa26a5754f8', '95953cbf-395b-485f-8506-375c0ae0510d', 7, 'Using a sharp knife, cut into diamond or square shapes all the way through the top layers of phyllo; do not cut through the bottom layers.'),
('025e999e-853b-4698-84b8-b2420c07f0c6', '95953cbf-395b-485f-8506-375c0ae0510d', 8, 'Bake in the preheated oven until the phyllo is a deep golden brown, 50 to 60 minutes.'),
('2a9c9e27-62d8-49a5-8762-aef9c0d6e61e', '95953cbf-395b-485f-8506-375c0ae0510d', 9, 'Remove baklava from the oven and immediately ladle the cool syrup over the hot baklava. Add one ladleful at a time until all of the syrup has been added.'),
('cf7786af-fc58-42a8-8b9c-6e1dea57155e', '95953cbf-395b-485f-8506-375c0ae0510d', 10, 'Set aside and let rest, uncovered, for 8 hours or overnight before serving.');
insert into public.recipe_step_translations (step_id, locale, instruction) values
('6e17967c-c8cb-4028-88bd-638daf26df64', 'en', 'Combine chili sauce, soy sauce, Sriracha, lime zest, lime juice, granulated garlic, minced ginger, peanut butter, and salt to taste in a large resealable plastic bag. Gently move and mash the ingredients inside the bag until well blended.'),
('6e17967c-c8cb-4028-88bd-638daf26df64', 'ko', 'Combine chili sauce, soy sauce, Sriracha, lime zest, lime juice, granulated garlic, minced ginger, peanut butter, and salt to taste in a large resealable plastic bag. Gently move and mash the ingredients inside the bag until well blended.'),
('8300f948-7f2f-47ed-8c98-c7c2b85a36bc', 'en', 'Add chicken to the bag, and squeeze out as much air as possible. Move chicken around inside the bag until each piece is coated in marinade. Marinate in the refrigerator for at least 30 minutes and up to 24 hours.'),
('8300f948-7f2f-47ed-8c98-c7c2b85a36bc', 'ko', 'Add chicken to the bag, and squeeze out as much air as possible. Move chicken around inside the bag until each piece is coated in marinade. Marinate in the refrigerator for at least 30 minutes and up to 24 hours.'),
('45dbad4f-e7e1-4f2f-8730-9fa721d3d574', 'en', 'Preheat an air fryer to 350 degrees F (180 degrees C), or according to manufacturer''s recommendations.'),
('45dbad4f-e7e1-4f2f-8730-9fa721d3d574', 'ko', 'Preheat an air fryer to 350 degrees F (180 degrees C), or according to manufacturer''s recommendations.'),
('7882ceff-68e5-4150-854f-ee2347b36181', 'en', 'Spray the cooking surface of the air fryer with cooking spray.'),
('7882ceff-68e5-4150-854f-ee2347b36181', 'ko', 'Spray the cooking surface of the air fryer with cooking spray.'),
('0ad417f8-9258-47b7-8aee-0b110b2225b4', 'en', 'Take chicken pieces from the bag, and allow the marinade to drip back into the bag. Place chicken pieces in the air fryer in a single layer and air fry for 20 to 22 minutes, turning halfway through, until an instant-read thermometer inserted near the center reads 165 degrees F (74 degrees C).'),
('0ad417f8-9258-47b7-8aee-0b110b2225b4', 'ko', 'Take chicken pieces from the bag, and allow the marinade to drip back into the bag. Place chicken pieces in the air fryer in a single layer and air fry for 20 to 22 minutes, turning halfway through, until an instant-read thermometer inserted near the center reads 165 degrees F (74 degrees C).'),
('9296d22a-4465-4937-875e-5d6f57ee189a', 'en', 'Meanwhile, add about 1/2 cup of water to the unused marinade, and mix contents; pour into a microwave-safe container. Microwave on High, until marinade comes to a boil, and cook about 1 minute longer; watch carefully to see it does not boil over.'),
('9296d22a-4465-4937-875e-5d6f57ee189a', 'ko', 'Meanwhile, add about 1/2 cup of water to the unused marinade, and mix contents; pour into a microwave-safe container. Microwave on High, until marinade comes to a boil, and cook about 1 minute longer; watch carefully to see it does not boil over.'),
('4218c721-f27b-43c6-891c-d3b63248d59f', 'en', 'Serve chicken over rice, with sauce on the side as a dip. Garnish with chopped cilantro, sliced scallions, julienne cucumbers and carrots, and chopped peanuts, as desired.'),
('4218c721-f27b-43c6-891c-d3b63248d59f', 'ko', 'Serve chicken over rice, with sauce on the side as a dip. Garnish with chopped cilantro, sliced scallions, julienne cucumbers and carrots, and chopped peanuts, as desired.'),
('dc1c19c1-f75e-495d-8ea5-d5f782fc3dfe', 'en', 'Place bacon in a large skillet and cook over medium-high heat, turning occasionally, until evenly browned, about 10 minutes. Drain bacon slices on paper towels. Once cool enough to handle, roughly chop.'),
('dc1c19c1-f75e-495d-8ea5-d5f782fc3dfe', 'ko', 'Place bacon in a large skillet and cook over medium-high heat, turning occasionally, until evenly browned, about 10 minutes. Drain bacon slices on paper towels. Once cool enough to handle, roughly chop.'),
('8cf2c7b4-3280-46e8-8d71-ac4199852f7b', 'en', 'Meanwhile, preheat an air fryer oven to 400 degrees F (200 degrees C).'),
('8cf2c7b4-3280-46e8-8d71-ac4199852f7b', 'ko', 'Meanwhile, preheat an air fryer oven to 400 degrees F (200 degrees C).'),
('3c3c21b1-cb37-451e-88ee-99da3052e0dc', 'en', 'Air fry the waffle fries until golden and crispy, shaking halfway through, for 8 to 10 minutes or bake as directed on the package. Be sure to flip the half way through baking.'),
('3c3c21b1-cb37-451e-88ee-99da3052e0dc', 'ko', 'Air fry the waffle fries until golden and crispy, shaking halfway through, for 8 to 10 minutes or bake as directed on the package. Be sure to flip the half way through baking.'),
('c66383b7-a2cf-4147-8c33-d7e388041692', 'en', 'Preheat the oven to 375 degrees F (190 degrees C).'),
('c66383b7-a2cf-4147-8c33-d7e388041692', 'ko', 'Preheat the oven to 375 degrees F (190 degrees C).'),
('3ce64a46-9af2-4c7a-8f9e-d85ead5c5055', 'en', 'Heat olive oil in a large skillet over medium heat. Add onions and cook until softened, 2 to 3 minutes. Add minced garlic and cook until fragrant, about 30 seconds. Add ground beef and season with salt and pepper. Cook and stir ground beef in the hot skillet until browned and crumbly, breaking up any clumps as it cooks, 5 to 7 minutes. Drain and discard grease. Stir in ketchup, mustard, and mayonnaise to completely coat the beef mixture. Simmer for 1 to 2 minutes.'),
('3ce64a46-9af2-4c7a-8f9e-d85ead5c5055', 'ko', 'Heat olive oil in a large skillet over medium heat. Add onions and cook until softened, 2 to 3 minutes. Add minced garlic and cook until fragrant, about 30 seconds. Add ground beef and season with salt and pepper. Cook and stir ground beef in the hot skillet until browned and crumbly, breaking up any clumps as it cooks, 5 to 7 minutes. Drain and discard grease. Stir in ketchup, mustard, and mayonnaise to completely coat the beef mixture. Simmer for 1 to 2 minutes.'),
('b5a6889e-00b5-4095-8055-2af1c3413a63', 'en', 'Preheat the oven to 375 degrees C (190 degrees C).'),
