('f7f0ef68-d7df-4fba-8daf-62589faac4db', 'ko', 'Gather the ingredients.'),
('95bd30ce-4d01-4abf-8387-9b0ee89c991d', 'en', 'Dip eggplant slices in egg, then coat with bread crumbs. Heat olive oil in a large skillet over medium-high heat.'),
('95bd30ce-4d01-4abf-8387-9b0ee89c991d', 'ko', 'Dip eggplant slices in egg, then coat with bread crumbs. Heat olive oil in a large skillet over medium-high heat.'),
('a0d752aa-a8da-40cd-8ae8-82714799fca6', 'en', 'Fry eggplant slices on each side until golden brown. Remove to a paper towel lined plate to drain. Preheat the oven to 350 degrees F (175 degrees C).'),
('a0d752aa-a8da-40cd-8ae8-82714799fca6', 'ko', 'Fry eggplant slices on each side until golden brown. Remove to a paper towel lined plate to drain. Preheat the oven to 350 degrees F (175 degrees C).'),
('7c834327-8258-4aad-8f44-f1a912ccda89', 'en', 'Spread a thin layer of ricotta cheese onto each slice of eggplant. Place a slice of prosciutto onto each one. Roll up tightly, and place seam-side down in a 9x13-inch baking dish. Pour tomato pasta sauce over eggplant rolls, and top with shredded mozzarella cheese.'),
('7c834327-8258-4aad-8f44-f1a912ccda89', 'ko', 'Spread a thin layer of ricotta cheese onto each slice of eggplant. Place a slice of prosciutto onto each one. Roll up tightly, and place seam-side down in a 9x13-inch baking dish. Pour tomato pasta sauce over eggplant rolls, and top with shredded mozzarella cheese.'),
('d81ff1ae-9a1a-43e0-8241-b669e83dd4db', 'en', 'Bake for 15 minutes in the preheated oven, until the cheese is melted and lightly browned.'),
('d81ff1ae-9a1a-43e0-8241-b669e83dd4db', 'ko', 'Bake for 15 minutes in the preheated oven, until the cheese is melted and lightly browned.'),
('22926996-eff3-4d2a-82b0-1f2a9da169d8', 'en', 'If you want to serve the eggplant rollatini on pasta, bring a large pot of lightly salted water to a boil while eggplant rolls are baking. Add pasta, and cook for 2 to 3 minutes, until tender. Drain.'),
('22926996-eff3-4d2a-82b0-1f2a9da169d8', 'ko', 'If you want to serve the eggplant rollatini on pasta, bring a large pot of lightly salted water to a boil while eggplant rolls are baking. Add pasta, and cook for 2 to 3 minutes, until tender. Drain.'),
('137e8ba5-f32c-40ad-87bc-a04a2f22a7b5', 'en', 'Serve eggplant rolls and sauce over pasta.'),
('137e8ba5-f32c-40ad-87bc-a04a2f22a7b5', 'ko', 'Serve eggplant rolls and sauce over pasta.'),
('73edfdff-8dfe-4e4e-87aa-df26ae4d2581', 'en', 'Preheat the oven to 400 degrees F (200 degrees C). Prick each potato a few times with a fork and place on a baking sheet.'),
('73edfdff-8dfe-4e4e-87aa-df26ae4d2581', 'ko', 'Preheat the oven to 400 degrees F (200 degrees C). Prick each potato a few times with a fork and place on a baking sheet.'),
('4c5b195b-4adf-43d4-8d1d-c63dad411a68', 'en', 'Bake potatoes in the preheated oven until tender when pierced with a knife, about 50 minutes. Cool until easily handled, about 10 minutes.'),
('4c5b195b-4adf-43d4-8d1d-c63dad411a68', 'ko', 'Bake potatoes in the preheated oven until tender when pierced with a knife, about 50 minutes. Cool until easily handled, about 10 minutes.'),
('8fb69786-88f1-46aa-8637-0ff8bbb21598', 'en', 'Peel potatoes and pass through a ricer or food mill into a large bowl. Make a well in the center and pour in egg; mix well.'),
